import numpy as np
import time


def C_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    # Build initial heights: use start if given, else a smooth bump.
    if start is not None:
        h0 = np.asarray(start, dtype=float).copy()
        if h0.ndim != 1 or h0.size == 0 or h0.sum() <= 0:
            h0 = np.ones(50)
    else:
        N0 = 50
        x = (np.arange(N0) + 0.5) / N0 - 0.5
        h0 = np.maximum(1.0 - np.abs(2 * x), 0.0) ** 2 + 1e-3

    h0 = np.maximum(h0, 0.0)

    # Split every step into 4 equal copies: same function, same C, N x4.
    h = np.repeat(h0, 4)
    h = np.maximum(h, 1e-12)

    best = h.copy()
    bestC = C_of(best)
    cur = best.copy()
    curC = bestC

    deltas = [0.2, 0.1, 0.05, 0.02, 0.01]

    def try_update(idx, factor):
        nonlocal cur, curC, best, bestC
        cand = cur.copy()
        cand[idx] *= factor
        cC = C_of(cand)
        if cC < curC - 1e-15:
            cur = cand
            curC = cC
            if curC < bestC:
                best = cur.copy()
                bestC = curC
            return True
        return False

    # Deterministic descent: sweep coordinates and blocks, shrinking delta.
    while time.process_time() < deadline:
        improved_any = False
        for delta in deltas:
            if time.process_time() >= deadline:
                break
            up = np.exp(delta)
            down = np.exp(-delta)
            # Single-coordinate sweeps
            N = cur.size
            for i in range(N):
                if time.process_time() >= deadline:
                    break
                if try_update(i, up):
                    improved_any = True
                    continue
                if try_update(i, down):
                    improved_any = True
            # Block sweeps of size 2..5
            for bsize in (2, 3, 4, 5):
                if time.process_time() >= deadline:
                    break
                N = cur.size
                for i0 in range(0, N - bsize + 1):
                    if time.process_time() >= deadline:
                        break
                    idx = slice(i0, i0 + bsize)
                    if try_update(idx, up):
                        improved_any = True
                        continue
                    if try_update(idx, down):
                        improved_any = True
        if not improved_any:
            # No improvement at smallest delta: try a tiny extra shrink once
            if time.process_time() >= deadline:
                break
            # Attempt a final fine sweep with a very small delta
            up = np.exp(0.005)
            down = np.exp(-0.005)
            N = cur.size
            any2 = False
            for i in range(N):
                if time.process_time() >= deadline:
                    break
                if try_update(i, up):
                    any2 = True
                    continue
                if try_update(i, down):
                    any2 = True
            if not any2:
                break

    return np.maximum(best, 0.0)

import numpy as np
import time
from scipy.signal import fftconvolve


def _C(h):
    s = h.sum()
    if s <= 0 or not np.isfinite(s):
        return np.inf
    N = h.size
    m = fftconvolve(h, h, mode='full').max()
    return 2.0 * N * m / (s * s)


def _resample(h, N):
    h = np.asarray(h, dtype=float)
    M = h.size
    if M == N:
        return h.copy()
    xi = np.linspace(0.0, 1.0, M)
    xo = np.linspace(0.0, 1.0, N)
    return np.interp(xo, xi, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    best_h = None
    best_C = np.inf

    candidates = []
    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.ndim == 1 and hs.size > 0 and hs.sum() > 0 and np.all(np.isfinite(hs)):
            candidates.append(np.maximum(hs, 0.0))
    for N in (50, 200, 1000, 4000):
        x = -0.25 + (np.arange(N) + 0.5) / (2.0 * N)
        candidates.append(np.cos(2 * np.pi * x) ** 4)
        for lam in (2.0, 4.0, 6.0):
            candidates.append(np.exp(lam * x))

    for c in candidates:
        if time.process_time() > deadline:
            break
        cc = _C(c)
        if cc < best_C:
            best_C, best_h = cc, c.copy()

    rng = np.random.default_rng(2024)

    def refine(h, iterations, deadline, step0=0.15):
        h = np.maximum(np.asarray(h, dtype=float), 1e-9)
        cur = h.copy()
        curC = _C(cur)
        best = cur.copy()
        bC = curC
        N = cur.size
        step = step0
        for it in range(iterations):
            if time.process_time() > deadline:
                break
            i = int(rng.integers(0, N))
            cand = cur.copy()
            cand[i] *= np.exp(rng.normal(0.0, step))
            cC = _C(cand)
            if cC < curC:
                cur, curC = cand, cC
                if curC < bC:
                    best, bC = cur.copy(), curC
            if it % 500 == 499:
                step *= 0.9
                if step < 1e-3:
                    cur = best.copy()
                    curC = bC
                    step = step0 * 0.5
        return best, bC

    N1 = 400
    h1 = _resample(best_h, N1)
    h1, c1 = refine(h1, iterations=20000, deadline=deadline, step0=0.2)
    if c1 < best_C:
        best_C, best_h = c1, h1.copy()

    if time.process_time() < deadline:
        N2 = 2000
        h2 = _resample(best_h, N2)
        h2, c2 = refine(h2, iterations=20000, deadline=deadline, step0=0.1)
        if c2 < best_C:
            best_C, best_h = c2, h2.copy()

    if time.process_time() < deadline:
        N3 = 6000
        h3 = _resample(best_h, N3)
        h3, c3 = refine(h3, iterations=20000, deadline=deadline, step0=0.05)
        if c3 < best_C:
            best_C, best_h = c3, h3.copy()

    if best_h is None:
        best_h = np.ones(50)
    return np.maximum(best_h, 0.0)

import numpy as np
import time
from scipy.signal import fftconvolve


def C_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * fftconvolve(h, h, 'full').max() / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.78

    def remaining():
        return deadline - time.process_time()

    def upsample(h, Nnew):
        Nold = len(h)
        if Nold == Nnew:
            return h.copy()
        idx = np.linspace(0, Nold - 1, Nnew)
        lo = np.floor(idx).astype(int)
        hi = np.minimum(lo + 1, Nold - 1)
        w = idx - lo
        return h[lo] * (1 - w) + h[hi] * w

    # ---- seeds ----
    def make_exp(N, a):
        x = np.linspace(-1.0, 1.0, N)
        h = np.exp(a * x)
        return h / h.sum()

    def make_parab(N):
        x = np.linspace(-1.0, 1.0, N)
        h = np.maximum(1.0 - x * x, 0.0)
        return h / h.sum()

    candidates = []
    for N in (200, 400, 800, 1500):
        for a in (0.5, 1.0, 2.0, 3.0, 5.0):
            candidates.append(make_exp(N, a))
        candidates.append(make_parab(N))

    best_h = None
    best_C = np.inf

    if start is not None:
        hs = np.asarray(start, dtype=float).ravel()
        if hs.size > 0 and hs.sum() > 0:
            cs = C_of(hs)
            best_h = hs.copy()
            best_C = cs

    for h in candidates:
        if time.process_time() > deadline:
            break
        c = C_of(h)
        if c < best_C:
            best_C = c
            best_h = h.copy()

    if best_h is None:
        best_h = np.ones(50)
        best_C = C_of(best_h)

    # ---- Upsample best seed to larger N and check ----
    for N in (400, 800, 1500, 3000, 5000, 8000):
        if time.process_time() > deadline:
            break
        h = upsample(best_h, N)
        c = C_of(h)
        if c < best_C:
            best_C = c
            best_h = h.copy()

    # ---- Analytic-gradient descent on C (log-space, scale invariant) ----
    # We minimize C(h) = 2N * max(conv(h,h)) / (sum h)^2.
    # Using the active knot k: grad wrt h_i is
    #   dC/dh_i = 2N * [ 2*h_{k-i} / s^2 - 2*m / s^3 ]
    # (factor 2 in the conv derivative since both factors vary).
    # Then step in log space: dh_i = -eta * h_i * grad_i.
    def refine(h, local_deadline, iters_cap=200000):
        N = len(h)
        cur = h.astype(float).copy()
        s = cur.sum()
        if s <= 0:
            return cur, np.inf
        cur /= s
        curC = C_of(cur)
        best = cur.copy()
        bestC = curC
        eta = 0.02
        stall = 0
        it = 0
        while time.process_time() < local_deadline and it < iters_cap:
            it += 1
            conv = fftconvolve(cur, cur, 'full')
            m = conv.max()
            k = int(np.argmax(conv))
            s = cur.sum()
            grad = np.zeros(N)
            lo = max(0, k - (N - 1))
            hi = min(N - 1, k)
            idx = np.arange(lo, hi + 1)
            # d(conv_k)/dh_i = 2 * h_{k-i}
            grad[idx] = 2.0 * N * (2.0 * cur[k - idx] / (s * s)
                                   - 2.0 * m / (s * s * s))
            step = -eta * grad * cur
            newh = cur + step
            newh = np.maximum(newh, 0.0)
            ss = newh.sum()
            if ss <= 0:
                eta *= 0.5
                if eta < 1e-10:
                    break
                continue
            newh /= ss
            nc = C_of(newh)
            if nc < curC - 1e-15:
                cur, curC = newh, nc
                stall = 0
                eta *= 1.03
                if curC < bestC:
                    best, bestC = cur.copy(), curC
            else:
                stall += 1
                eta *= 0.7
                if eta < 1e-10:
                    cur = best.copy()
                    curC = bestC
                    eta = 1e-3
                    if stall > 3000:
                        break
        return best, bestC

    # Alternate: refine at current N, then grow N and refine again.
    h = best_h.copy()
    while time.process_time() < deadline:
        slice_end = min(deadline, time.process_time() + 2.0)
        h, c = refine(h, slice_end)
        if c < best_C:
            best_C = c
            best_h = h.copy()
        if len(best_h) < 29000:
            Nnew = min(30000, int(len(best_h) * 1.4) + 20)
            h2 = upsample(best_h, Nnew)
            c2 = C_of(h2)
            if c2 <= best_C * 1.05:
                h = h2
                if c2 < best_C:
                    best_C = c2
                    best_h = h2.copy()
            else:
                h = best_h.copy()
        else:
            h = best_h.copy()

    # Final compare with start
    bh = np.maximum(best_h, 0.0)
    if bh.sum() > 0:
        if start is not None:
            hs = np.asarray(start, dtype=float).ravel()
            if hs.size > 0 and hs.sum() > 0:
                if C_of(hs) < C_of(bh):
                    return hs
        return bh
    if start is not None:
        return np.asarray(start, dtype=float).ravel()
    return np.ones(50)

import numpy as np
import time
from scipy.optimize import minimize


def C_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.80

    # Base: start resampled to a moderate N, else a smooth bump.
    if start is not None:
        h0 = np.asarray(start, dtype=float).ravel()
        if h0.size == 0 or h0.sum() <= 0:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N0 = 200
        x = (np.arange(N0) + 0.5) / N0 - 0.5
        h0 = np.maximum(1.0 - np.abs(2 * x), 0.0) ** 2 + 1e-3

    # Work at a fixed moderate resolution: N ~ 2 * start size (capped).
    N = int(min(4000, max(200, 2 * h0.size)))
    # Resample h0 to N via linear interpolation over the step centers.
    xs = (np.arange(h0.size) + 0.5) / h0.size
    xn = (np.arange(N) + 0.5) / N
    h = np.interp(xn, xs, h0)
    h = np.maximum(h, 1e-12)

    best = h.copy()
    bestC = C_of(best)

    # Parameterize by log-heights, use L-BFGS-B on smooth surrogate.
    # The objective max(conv) is piecewise smooth; we optimize with
    # finite-difference gradient via scipy and rely on the exact C check.
    def unpack(z):
        return np.exp(z - z.max())

    def obj(z):
        return C_of(unpack(z))

    z0 = np.log(best + 1e-12)
    z0 = z0 - z0.mean()

    # A few restarts with different sizes / smoothing.
    sizes = [N]
    for extra in (int(N * 1.5), int(N * 2.5)):
        if extra <= 30000 and extra not in sizes:
            sizes.append(extra)

    for Ntry in sizes:
        if time.process_time() >= deadline:
            break
        # Resample current best to Ntry
        xs = (np.arange(best.size) + 0.5) / best.size
        xn = (np.arange(Ntry) + 0.5) / Ntry
        hb = np.maximum(np.interp(xn, xs, best), 1e-12)
        cb = C_of(hb)
        if cb < bestC:
            best, bestC = hb.copy(), cb

        # Small initial smoothing to escape local minima
        hb = hb + 1e-3 * hb.mean()
        z = np.log(hb + 1e-12)
        z = z - z.mean()

        for smooth in (1e-3, 1e-4, 1e-5):
            if time.process_time() >= deadline:
                break
            try:
                res = minimize(
                    lambda zz: C_of(smooth_conv(unpack(zz), smooth)),
                    z, method='L-BFGS-B',
                    options={'maxiter': 200, 'ftol': 1e-12, 'gtol': 1e-10},
                )
                z = res.x
                cand = unpack(z)
                cc = C_of(cand)
                if cc < bestC:
                    best, bestC = cand.copy(), cc
            except Exception:
                pass

    return np.maximum(best, 0.0)


def smooth_conv(h, eps):
    # light smoothing to make C differentiable enough for L-BFGS
    if eps <= 0:
        return h
    k = np.array([eps, 1.0, eps])
    return np.convolve(h, k / k.sum(), mode='same')

import numpy as np
import time
from scipy.optimize import minimize, NonlinearConstraint


def C_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def conv_and_jac(h):
    """Return conv(h,h) and its Jacobian (2N-1 x N)."""
    N = h.size
    c = np.convolve(h, h)
    # d/dh_j conv(h,h)_k = h[k-j] + h[k-j]  (with bounds)
    J = np.zeros((c.size, N))
    for j in range(N):
        # contribution: h[j]*h[k-j] terms; derivative wrt h[j]:
        # conv_k = sum_i h[i] h[k-i]; d/dh_j = h[k-j] + h[j-k]... but symmetric
        # Actually d/dh_j conv_k = h[k-j] (if 0<=k-j<N) + h[k-j]... no:
        # conv_k = sum_i h_i h_{k-i}. d/dh_j = h_{k-j} + h_{k-j}? No:
        # d/dh_j sum_i h_i h_{k-i} = h_{k-j} (from i=j) + h_{k-j} (from k-i=j => i=k-j)
        # = h[k-j] + h[k-j] but only if both indices valid; they're the same index.
        # Wait: i=j gives h_{k-j}; k-i=j gives i=k-j gives h_{k-j}. Same term twice.
        # So d/dh_j conv_k = 2*h[k-j] when 0<=k-j<N.
        lo = max(0, j)
        hi = min(c.size - 1, j + N - 1)
        ks = np.arange(lo, hi + 1)
        J[ks, j] = 2.0 * h[ks - j]
    return c, J


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.80

    # Build initial h: downsample/average start to N=80.
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size == 0 or s.sum() <= 0:
            s = np.ones(80)
    else:
        s = np.ones(80)

    N = 80
    if s.size != N:
        # average into N bins
        edges = np.linspace(0, s.size, N + 1)
        h0 = np.array([s[int(edges[i]):max(int(edges[i]) + 1, int(edges[i + 1]))].mean()
                       for i in range(N)])
    else:
        h0 = s.copy()
    h0 = np.maximum(h0, 1e-9)
    # Normalize so max conv ~ 1
    c0 = np.max(np.convolve(h0, h0))
    h0 = h0 / np.sqrt(c0) * 0.999

    best_h = h0.copy()
    best_C = C_of(h0)

    # SLSQP: maximize sum(h) s.t. conv(h,h) <= 1, h >= 0
    def obj(h):
        return -h.sum()

    def obj_jac(h):
        return -np.ones_like(h)

    def con_fun(h):
        return np.convolve(h, h)

    def con_jac(h):
        _, J = conv_and_jac(h)
        return J

    nlc = NonlinearConstraint(con_fun, -np.inf, 1.0, jac=con_jac)
    bounds = [(0.0, None)] * N

    x = h0.copy()
    try:
        res = minimize(obj, x, jac=obj_jac, method='SLSQP',
                       bounds=bounds, constraints=[nlc],
                       options={'maxiter': 500, 'ftol': 1e-12})
        if res.x is not None and np.all(np.isfinite(res.x)):
            hx = np.maximum(res.x, 0.0)
            if hx.sum() > 0:
                # rescale to be feasible-ish
                cmax = np.max(np.convolve(hx, hx))
                if cmax > 1.0:
                    hx = hx / np.sqrt(cmax)
                cC = C_of(hx)
                if cC < best_C:
                    best_h = hx.copy()
                    best_C = cC
    except Exception:
        pass

    # Local polishing: coordinate descent on the N=80 solution, then refine.
    cur = best_h.copy()
    curC = best_C
    deltas = [0.05, 0.02, 0.01, 0.005, 0.002]

    def try_update(idx, factor):
        nonlocal cur, curC, best_h, best_C
        cand = cur.copy()
        cand[idx] *= factor
        cC = C_of(cand)
        if cC < curC - 1e-15:
            cur = cand
            curC = cC
            if curC < best_C:
                best_h = cur.copy()
                best_C = curC
            return True
        return False

    while time.process_time() < deadline:
        improved = False
        for delta in deltas:
            if time.process_time() >= deadline:
                break
            up = np.exp(delta)
            down = np.exp(-delta)
            for i in range(cur.size):
                if time.process_time() >= deadline:
                    break
                if try_update(i, up):
                    improved = True
                    continue
                if try_update(i, down):
                    improved = True
        if not improved:
            break

    return np.maximum(best_h, 0.0)

import numpy as np
import time


def _C(h):
    s = h.sum()
    if s <= 0 or not np.isfinite(s):
        return np.inf
    N = h.size
    m = np.max(np.convolve(h, h))
    return 2.0 * N * m / (s * s)


def _resample(h, N):
    h = np.asarray(h, dtype=float)
    M = h.size
    if M == N:
        return h.copy()
    xi = np.linspace(0.0, 1.0, M)
    xo = np.linspace(0.0, 1.0, N)
    return np.interp(xo, xi, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.80

    best_h = None
    best_C = np.inf

    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.ndim == 1 and hs.size > 0 and hs.sum() > 0 and np.all(np.isfinite(hs)):
            hs = np.maximum(hs, 0.0)
            c = _C(hs)
            if c < best_C:
                best_C, best_h = c, hs.copy()

    # baseline if nothing given
    if best_h is None:
        N = 50
        x = -0.25 + (np.arange(N) + 0.5) / (2.0 * N)
        best_h = np.cos(2 * np.pi * x) ** 4
        best_C = _C(best_h)

    rng = np.random.default_rng(12345)

    def refine(h, iterations, deadline, step0):
        h = np.maximum(np.asarray(h, dtype=float), 1e-9)
        cur = h.copy()
        curC = _C(cur)
        best = cur.copy()
        bC = curC
        N = cur.size
        step = step0
        since_improve = 0
        for it in range(iterations):
            if (it & 63) == 0 and time.process_time() > deadline:
                break
            i = int(rng.integers(0, N))
            cand = cur.copy()
            cand[i] *= np.exp(rng.normal(0.0, step))
            cC = _C(cand)
            if cC < curC:
                cur, curC = cand, cC
                since_improve = 0
                if curC < bC:
                    best, bC = cur.copy(), curC
            else:
                since_improve += 1
            if since_improve > 300:
                step *= 0.97
                since_improve = 0
                if step < 1e-4:
                    cur = best.copy()
                    curC = bC
                    step = step0 * 0.3
        return best, bC

    # Always refine at the start's resolution first (cheap, exact), then grow N.
    schedules = []
    if best_h is not None:
        schedules.append((best_h.size, 40000, 0.15))
    for N, iters, step in ((200, 30000, 0.15), (800, 40000, 0.12),
                           (3000, 60000, 0.08), (10000, 80000, 0.05)):
        schedules.append((N, iters, step))

    for N, iters, step in schedules:
        if time.process_time() >= deadline:
            break
        h0 = _resample(best_h, N)
        h0, c0 = refine(h0, iters, deadline, step)
        if c0 < best_C:
            best_C, best_h = c0, h0.copy()

