    xi = np.linspace(0.0, 1.0, M)
    xo = np.linspace(0.0, 1.0, N)
    return np.interp(xo, xi, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.78

    # ---- seed ----
    best_h = None
    best_C = np.inf
    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.ndim == 1 and hs.size > 0 and hs.sum() > 0 and np.all(np.isfinite(hs)):
            hs = np.maximum(hs, 0.0)
            c = _C(hs)
            if c < best_C:
                best_C, best_h = c, hs.copy()
    if best_h is None:
        N = 60
        x = -0.25 + (np.arange(N) + 0.5) / (2.0 * N)
        best_h = np.cos(2 * np.pi * x) ** 4 + 1e-6
        best_C = _C(best_h)

    # ---- smoothed objective with true analytic gradient ----
    # parameterize by h directly (scale invariant), penalize sum via normalization
    def make_obj(N, beta):
        def f_and_g(u):
            h = np.maximum(u, 0.0)
            s = h.sum()
            if s <= 1e-30:
                return 1e10, np.zeros_like(u)
            conv = np.convolve(h, h)
            m = conv.max()
            z = beta * (conv - m)
            e = np.exp(z)
            se = e.sum()
            lse = m + np.log(se) / beta
            L = 2.0 * N * lse / (s * s)
            # d L / d h_k
            w = e / se
            # d lse / d conv[j] = w[j]
            # d conv[j] / d h_k = 2 h_{j-k} (valid indices)
            grad_lse = np.zeros(N)
            for k in range(N):
                jlo = k
                jhi = min(2 * N - 2, k + N - 1)
                if jlo > jhi:
                    continue
                # sum_j w[j] * 2 h[j-k]
                grad_lse[k] = 2.0 * np.dot(w[jlo:jhi + 1], h[jlo - k:jhi - k + 1])
            # L = 2N * lse / s^2
            # dL/dh = 2N/s^2 * grad_lse - 4N*lse/s^3 * 1
            g = (2.0 * N / (s * s)) * grad_lse - (4.0 * N * lse / (s ** 3))
            return L, g
        return f_and_g

    def polish(h, N, deadline, betas=(1e4, 1e5, 1e6, 1e7)):
        h = np.maximum(np.asarray(h, dtype=float), 1e-12)
        # normalize
        h = h / h.sum() * N
        for beta in betas:
            if time.process_time() >= deadline:
                break
            fg = make_obj(N, beta)
            try:
                res = minimize(fg, h, jac=True, method='L-BFGS-B',
                               options={'maxiter': 400, 'ftol': 1e-16, 'gtol': 1e-14})
                h = np.maximum(res.x, 0.0)
                if h.sum() <= 0:
                    break
                h = h / h.sum() * N
            except Exception:
                break
        return h

