        h_init = np.maximum(h_init, 1e-12)
        h2 = polish(h_init, N2, deadline)
        c2 = _C(h2)
        if c2 < best_C:
            best_C, best_h = c2, h2.copy()

    # ---- local pattern search on log-h, exact C (cheap, robust) ----
    def pattern(h, deadline):
        h = np.maximum(h.astype(float), 1e-30)
        N = h.size
        c = _C(h)
