                    return h, c
                old = h[i]
                for sgn in (1.0, -1.0):
                    h[i] = old * np.exp(sgn * step)
                    nc = _C(h)
                    if nc < c - 1e-15:
                        c = nc
                        old = h[i]
                        improved = True
                    else:
                        h[i] = old
            if not improved:
                step *= 0.5
        return h, c

    if time.process_time() < deadline:
        h3, c3 = pattern(best_h, deadline)
        if c3 < best_C:
            best_C, best_h = c3, h3.copy()

    if best_h is None:
        best_h = np.ones(50)
    return np.maximum(np.asarray(best_h, dtype=float), 0.0)

