    if start is not None:
        h0 = np.asarray(start, dtype=float).copy()
        if h0.ndim != 1 or h0.size == 0 or h0.sum() <= 0:
            h0 = np.ones(200)
    else:
        N0 = 200
        x = (np.arange(N0) + 0.5) / N0 - 0.5
        h0 = np.maximum(1.0 - np.abs(2 * x), 0.0) ** 2 + 1e-3

    h0 = np.maximum(h0, 1e-12)
    N = h0.size

    best = h0.copy()
    bestC = C_of(best)

    def C_fast(h):
        s = h.sum()
        if s <= 0:
            return np.inf
        return 2.0 * N * np.max(np.convolve(h, h)) / (s * s)

    def pack(h):
        x = np.log(np.maximum(h, 1e-30))
        return x - np.mean(x)

    def unpack(x):
        mx = np.max(x)
        e = np.exp(x - mx)
        return e / e.sum() * N

    # ---- Exact active-set subgradient L-BFGS on log-heights ----
    def make_active_L_and_grad():
        def L_and_grad(x):
            h = unpack(x)
            conv = np.convolve(h, h)
            M = np.max(conv)
            A = np.where(conv > M - 1e-12)[0]
            if A.size == 0:
                A = np.array([int(np.argmax(conv))])
            w = np.ones(A.size) / A.size
            L = 2.0 * N * M
            grad_conv = np.zeros(N)
            for idx, k in enumerate(A):
                jlo = k
                jhi = min(2 * N - 2, k + N - 1)
                if jlo > jhi:
                    continue
                grad_conv[k] += 2.0 * w[idx] * np.dot(
                    h[jlo - k:jhi - k + 1], h[jlo - k:jhi - k + 1])
            # dL/dh = 2N * grad_conv (with conv = h*h, d(conv[k])/dh[j] = 2 h[k-j])
            # Actually recompute properly:
            grad_conv = np.zeros(N)
            for idx, k in enumerate(A):
                jlo = max(0, k - (N - 1))
                jhi = min(N - 1, k)
                for j in range(jlo, jhi + 1):
                    grad_conv[j] += 2.0 * w[idx] * h[k - j]
            grad_h = 2.0 * N * grad_conv
            s = h / N  # softmax prob
            gx = N * s * (grad_h - np.sum(grad_h * s))
            return L, gx
        return L_and_grad

    def cb_factory():
        def cb(xk):
            nonlocal best, bestC
            h = unpack(xk)
            c = C_fast(h)
            if c < bestC:
                best = h.copy()
                bestC = c
        return cb

    x = pack(h0)
    if time.process_time() < deadline:
        Lg = make_active_L_and_grad()
        cb = cb_factory()
        try:
            res = minimize(Lg, x, method='L-BFGS-B', jac=True,
                           options={'maxiter': 500, 'ftol': 1e-16, 'gtol': 1e-14},
                           callback=cb)
            x = res.x
            cb(x)
        except Exception:
            pass

    # ---- p0043 extended_search on log-heights ----
    def extended_search(h):
        nonlocal best, bestC
        h = np.maximum(h.copy(), 1e-30)
        c = C_fast(h)
        if c < bestC:
            best = h.copy()
            bestC = c
        steps = [0.2, 0.1, 0.05, 0.02, 0.01, 0.005, 0.002, 0.001, 0.0005]
        for s in steps:
            if time.process_time() >= deadline:
                break
            for sweep in range(6):
                if time.process_time() >= deadline:
                    break
                improved = False
                for i in range(N):
                    if time.process_time() >= deadline:
                        break
                    old = h[i]
                    h[i] = old * np.exp(s)
                    nc = C_fast(h)
                    if nc < c - 1e-15:
                        c = nc
                        old = h[i]
                        improved = True
                        if c < bestC:
