                            bestC = c
                    else:
                        h[i] = old
                    h[i] = old * np.exp(-s)
                    nc = C_fast(h)
                    if nc < c - 1e-15:
                        c = nc
                        old = h[i]
                        improved = True
                        if c < bestC:
                            best = h.copy()
                            bestC = c
                    else:
                        h[i] = old
                if not improved:
                    break
        return h

    h_cur = unpack(x)
    if C_fast(h_cur) < bestC:
        best = h_cur.copy()
        bestC = C_fast(h_cur)
    extended_search(best)

    return np.maximum(best, 0.0)

