    return np.interp(xo, xi, h)


def _obj_grad(z):
    z = z - z.max()
    h = np.exp(z)
    N = h.size
    S = h.sum()
    conv = np.convolve(h, h)
    mx = conv.max()
    tol = 1e-12 * max(1.0, abs(mx))
    ks = np.where(conv >= mx - tol)[0]
    C = 2.0 * N * mx / (S * S)
    g = np.zeros(N)
    pref = 4.0 * N / (S ** 3)
    for k in ks:
        jlo = max(0, k - (N - 1))
        jhi = min(N - 1, k)
        if jlo > jhi:
            continue
        js = np.arange(jlo, jhi + 1)
        hkj = h[k - js]
        g[js] += h[js] * (S * hkj - conv[k])
    g *= pref / len(ks)
    return C, g


def _coordinate_polish(h, deadline, steps=(0.02, 0.01, 0.005, 0.002, 0.001)):
    h = h.copy()
    best = _C(h)
    N = h.size
    for st in steps:
        improved = True
        while improved:
            improved = False
            if time.process_time() > deadline:
                return h, best
            for i in range(N):
                if time.process_time() > deadline:
                    return h, best
                old = h[i]
                for fac in (1.0 + st, 1.0 - st):
                    h[i] = old * fac
                    c = _C(h)
                    if c < best - 1e-15:
                        best = c
                        old = h[i]
                        improved = True
                    else:
                        h[i] = old
                h[i] = old
    return h, best


def _extended_search(h, deadline, steps, max_sweeps=6):
    h = np.maximum(np.asarray(h, dtype=float), 1e-300)
    best = _C(h)
    N = h.size
    for st in steps:
        for sweep in range(max_sweeps):
            if time.process_time() > deadline:
                return h, best
            improved = False
            for i in range(N):
                if time.process_time() > deadline:
                    return h, best
                old = h[i]
                for fac in (1.0 + st, 1.0 - st):
                    h[i] = old * fac
                    c = _C(h)
                    if c < best - 1e-15:
                        best = c
                        old = h[i]
                        improved = True
                    else:
                        h[i] = old
                h[i] = old
            if not improved:
                break
    return h, best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    best_h = None
    best_C = np.inf

    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.ndim == 1 and hs.size > 0 and hs.sum() > 0 and np.all(np.isfinite(hs)):
            hs = np.maximum(hs, 0.0)
            c = _C(hs)
            if c < best_C:
                best_C, best_h = c, hs.copy()

    if best_h is None:
        N = 100
        x = -0.25 + (np.arange(N) + 0.5) / (2.0 * N)
        best_h = np.cos(2 * np.pi * x) ** 4
        best_C = _C(best_h)

    N = best_h.size
    h0 = np.maximum(best_h.astype(float), 1e-12)
    z = np.log(h0)
    z = z - z.max()

    try:
        res = minimize(_obj_grad, z, method='L-BFGS-B', jac=True,
                       options={'maxiter': 500, 'ftol': 1e-15, 'gtol': 1e-12})
        z = res.x
        h = np.exp(z - z.max())
        c = _C(h)
        if c < best_C:
            best_C, best_h = c, h.copy()
    except Exception:
        pass

    if time.process_time() < deadline:
        h, c = _coordinate_polish(best_h, deadline)
        if c < best_C:
            best_C, best_h = c, h.copy()

    steps = [0.2, 0.1, 0.05, 0.02, 0.01, 0.005, 0.002, 0.001,
             0.0005, 0.0002, 0.0001, 0.00005, 0.00002, 0.00001]
    if time.process_time() < deadline:
        h, c = _extended_search(best_h, deadline, steps, max_sweeps=6)
        if c < best_C:
            best_C, best_h = c, h.copy()

    if best_h is None:
        best_h = np.ones(50)
    return np.maximum(np.asarray(best_h, dtype=float), 0.0)

import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0 or not np.isfinite(s):
        return np.inf
    N = h.size
    m = np.max(np.convolve(h, h))
    return 2.0 * N * m / (s * s)


def _resample(h, N):
    h = np.asarray(h, dtype=float)
    M = h.size
    if M == N:
        return h.copy()
    xi = (np.arange(M) + 0.5) / M
    xo = (np.arange(N) + 0.5) / N
    return np.interp(xo, xi, h)


def _make_obj(N):
    # Exact objective with subgradient wrt h (vectorized argmax gradient).
    def f_and_g(v):
        h = np.maximum(v, 0.0)
        s = h.sum()
        if s <= 0:
            return 1e10, np.zeros(N)
        conv = np.convolve(h, h)
        m = conv.max()
        idx = np.flatnonzero(conv >= m - 1e-15 * max(1.0, m))
        C = 2.0 * N * m / (s * s)
        # gradient of m wrt h: sum over argmax j of 2*h[j-k]; vectorize
        gconv = np.zeros(N)
        w = 1.0 / idx.size
        # For each j in idx, add 2*h[j-k] to gconv[k] for k in [j-N+1, j] clipped.
        # Equivalent: gconv[k] = sum_j 2*h[j-k]. Use correlation.
        mask = np.zeros(2 * N - 1)
        mask[idx] = w
        gconv = 2.0 * np.convolve(mask, h[::-1])[N - 1:2 * N - 1]
        g = 2.0 * N / (s * s) * gconv - 4.0 * N * m / (s ** 3)
        g = np.where((h <= 0) & (g > 0), 0.0, g)
        return C, g
    return f_and_g


def _refine(h, N, deadline, maxiter=3000):
    fg = _make_obj(N)
    v = np.maximum(h, 1e-12)
    v = v / v.sum() * N
    try:
        res = minimize(fg, v, method='L-BFGS-B', jac=True,
                       options={'maxiter': maxiter, 'ftol': 1e-18, 'gtol': 1e-15})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.80

    best_h = None
    best_C = np.inf
    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.ndim == 1 and hs.size > 0 and hs.sum() > 0 and np.all(np.isfinite(hs)):
            hs = np.maximum(hs, 0.0)
            c = _C(hs)
            if c < best_C:
                best_C, best_h = c, hs.copy()

    if best_h is None:
        N = 100
        x = (np.arange(N) + 0.5) / N - 0.5
        best_h = np.cos(np.pi * x) ** 4 + 1e-3
        best_C = _C(best_h)

    # First, aggressively refine at the current N (highest-value move)
    N0 = best_h.size
    if time.process_time() < deadline:
        h = _refine(best_h, N0, deadline, maxiter=5000)
        c = _C(h)
        if c < best_C:
            best_C, best_h = c, h.copy()

    # Multi-scale refinement: try smaller and larger N, refining each
    Ns = []
    for N in (N0, max(2, N0 // 2), N0 * 2, 60, 80, 120, 150, 200, 250, 300,
              400, 500, 700, 1000):
        if 2 <= N <= 30000 and N not in Ns:
            Ns.append(N)

    for N in Ns:
        if time.process_time() > deadline:
            break
        h_init = _resample(best_h, N)
        h_init = np.maximum(h_init, 1e-9)
        h_init = h_init / h_init.sum() * N
        h = _refine(h_init, N, deadline, maxiter=1500)
        c = _C(h)
        if c < best_C:
            best_C, best_h = c, h.copy()
            # extra polish at this new best N
            if time.process_time() < deadline:
                h2 = _refine(best_h, N, deadline, maxiter=3000)
                c2 = _C(h2)
                if c2 < best_C:
                    best_C, best_h = c2, h2.copy()

    # Small random restarts to escape local minima at best N
    if time.process_time() < deadline:
        N = best_h.size
        rng = np.random.default_rng(777)
        tries = 0
        while time.process_time() < deadline and tries < 20:
            tries += 1
            vp = np.maximum(best_h, 1e-12) * (1.0 + 5e-3 * rng.standard_normal(N))
            vp = np.maximum(vp, 0.0)
            if vp.sum() <= 0:
                continue
            h2 = _refine(vp, N, deadline, maxiter=800)
            c2 = _C(h2)
            if c2 < best_C:
                best_C, best_h = c2, h2.copy()

    # Final polish
    if time.process_time() < deadline:
        N = best_h.size
        h = _refine(best_h, N, deadline, maxiter=5000)
        c = _C(h)
        if c < best_C:
            best_C, best_h = c, h

    return np.maximum(np.asarray(best_h, dtype=float), 0.0)

