    if M == N:
        return h.copy()
    # piecewise-constant -> sample at new midpoints (better than linear for step funcs)
    pos = (np.arange(N) + 0.5) * (M / N) - 0.5
    pos = np.clip(pos, 0.0, M - 1.0)
    lo = np.floor(pos).astype(int)
    hi = np.minimum(lo + 1, M - 1)
    frac = pos - lo
    return (1.0 - frac) * h[lo] + frac * h[hi]


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    best_h = None
    best_C = np.inf

    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.ndim == 1 and hs.size > 0 and hs.sum() > 0 and np.all(np.isfinite(hs)):
            hs = np.maximum(hs, 0.0)
            c = _C(hs)
            if c < best_C:
                best_C, best_h = c, hs.copy()

    if best_h is None:
        N = 50
        x = -0.25 + (np.arange(N) + 0.5) / (2.0 * N)
        best_h = np.cos(2 * np.pi * x) ** 4
        best_C = _C(best_h)

    rng = np.random.default_rng(12345)

    def refine(h, iterations, deadline, step0):
        h = np.maximum(np.asarray(h, dtype=float), 1e-9)
        cur = h.copy()
        curC = _C(cur)
        best = cur.copy()
        bC = curC
        N = cur.size
        step = step0
        since_improve = 0
        for it in range(iterations):
            if (it & 63) == 0 and time.process_time() > deadline:
                break
            if rng.random() < 0.15:
                cand = cur.copy()
                L = int(rng.integers(1, max(2, N // 4 + 1)))
                start_i = int(rng.integers(0, max(1, N - L + 1)))
                cand[start_i:start_i + L] *= np.exp(rng.normal(0.0, step))
                cC = _C(cand)
                if cC < curC:
                    cur, curC = cand, cC
                    since_improve = 0
                    if curC < bC:
                        best, bC = cur.copy(), curC
                else:
                    since_improve += 1
            else:
                i = int(rng.integers(0, N))
                cand = cur.copy()
                cand[i] *= np.exp(rng.normal(0.0, step))
                cC = _C(cand)
                if cC < curC:
                    cur, curC = cand, cC
                    since_improve = 0
                    if curC < bC:
                        best, bC = cur.copy(), curC
                else:
                    since_improve += 1
            if since_improve > 250:
                step *= 0.97
                since_improve = 0
                if step < 1e-4:
                    cur = best.copy()
                    curC = bC
                    step = step0 * 0.3
        return best, bC

    def pattern_search(h, deadline):
        """Deterministic coordinate pattern search on log-heights."""
        nonlocal best_h, best_C
        h = np.maximum(np.asarray(h, dtype=float).copy(), 1e-15)
        N = h.size

        def C_fast(hh):
            s = hh.sum()
            if s <= 0:
                return np.inf
            return 2.0 * N * np.max(np.convolve(hh, hh)) / (s * s)

        c = C_fast(h)
        if c < best_C:
            best_C, best_h = c, h.copy()
        steps = [0.1, 0.05, 0.02, 0.01, 0.005, 0.002, 0.001, 0.0005,
                 0.0002, 0.0001, 5e-5, 2e-5, 1e-5, 5e-6, 2e-6, 1e-6]
        for s in steps:
            if time.process_time() >= deadline:
                break
            for sweep in range(4):
                if time.process_time() >= deadline:
                    break
                improved = False
                for i in range(N):
                    if (i & 15) == 0 and time.process_time() >= deadline:
                        break
                    old = h[i]
                    h[i] = old * np.exp(s)
                    nc = C_fast(h)
                    if nc < c - 1e-16:
                        c = nc
                        improved = True
                        if c < best_C:
                            best_C, best_h = c, h.copy()
                    else:
                        h[i] = old
                    h[i] = old * np.exp(-s)
                    nc = C_fast(h)
                    if nc < c - 1e-16:
                        c = nc
                        improved = True
                        if c < best_C:
                            best_C, best_h = c, h.copy()
                    else:
                        h[i] = old
                if not improved:
                    break
        return h

    # Phase 1: stochastic refinement on the given start
    schedules = []
    if best_h is not None:
        schedules.append((best_h.size, 40000, 0.15))
    for N, iters, step in ((200, 30000, 0.15), (800, 40000, 0.12),
                           (3000, 60000, 0.08), (10000, 80000, 0.05)):
        schedules.append((N, iters, step))

    for N, iters, step in schedules:
        if time.process_time() >= deadline:
            break
        h0 = _resample(best_h, N)
        h0, c0 = refine(h0, iters, deadline, step)
        if c0 < best_C:
            best_C, best_h = c0, h0.copy()

    # Phase 2: deterministic pattern search polish at current N and upsampled
    if time.process_time() < deadline:
        pattern_search(best_h, deadline)

    for target_N in (200, 400):
        if time.process_time() >= deadline:
            break
        if best_h.size >= target_N:
            continue
        h_up = _resample(best_h, target_N)
        h_up = np.maximum(h_up, 1e-12)
        h_up = h_up / h_up.sum() * target_N
        c_up = _C(h_up)
        if c_up < best_C:
            best_C, best_h = c_up, h_up.copy()
        pattern_search(best_h, deadline)

    if best_h is None:
        best_h = np.ones(50)
    return np.maximum(np.asarray(best_h, dtype=float), 0.0)

