    M = h.size
    if M == N:
        return h.copy()
    xi = np.linspace(0.0, 1.0, M)
    xo = np.linspace(0.0, 1.0, N)
    return np.interp(xo, xi, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.80

    # ---- seed ----
    best_h = None
    best_C = np.inf
    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.ndim == 1 and hs.size > 0 and hs.sum() > 0 and np.all(np.isfinite(hs)):
            hs = np.maximum(hs, 0.0)
            c = _C(hs)
            if c < best_C:
                best_C, best_h = c, hs.copy()
    if best_h is None:
        N = 100
        x = -0.25 + (np.arange(N) + 0.5) / (2.0 * N)
        best_h = np.cos(2 * np.pi * x) ** 4 + 1e-6
        best_C = _C(best_h)

    # ---- smoothed objective with analytic gradient ----
    def make_obj(N, beta):
        def f_and_g(u):
            h = np.maximum(u, 0.0)
            s = h.sum()
            if s <= 1e-30:
                return 1e10, np.zeros_like(u)
            conv = np.convolve(h, h)
            m = conv.max()
            z = beta * (conv - m)
            e = np.exp(z)
            se = e.sum()
            lse = m + np.log(se) / beta
            L = 2.0 * N * lse / (s * s)
            w = e / se
            grad_lse = np.zeros(N)
            for k in range(N):
                jlo = k
                jhi = min(2 * N - 2, k + N - 1)
                if jlo > jhi:
                    continue
                grad_lse[k] = 2.0 * np.dot(w[jlo:jhi + 1], h[jlo - k:jhi - k + 1])
            g = (2.0 * N / (s * s)) * grad_lse - (4.0 * N * lse / (s ** 3))
            return L, g
        return f_and_g

    def polish(h, N, deadline, betas=(1e4, 1e5, 1e6, 1e7, 1e8)):
        h = np.maximum(np.asarray(h, dtype=float), 1e-12)
        h = h / h.sum() * N
        for beta in betas:
            if time.process_time() >= deadline:
                break
            fg = make_obj(N, beta)
            try:
                res = minimize(fg, h, jac=True, method='L-BFGS-B',
                               options={'maxiter': 400, 'ftol': 1e-16, 'gtol': 1e-14})
                h = np.maximum(res.x, 0.0)
                if h.sum() <= 0:
                    break
                h = h / h.sum() * N
            except Exception:
                break
        return h

    # polish current best
    N = best_h.size
    h_p = polish(best_h, N, deadline)
    c = _C(h_p)
    if c < best_C:
        best_C, best_h = c, h_p.copy()

    # ---- try resampled sizes ----
    for N2 in (N, N * 2, max(2, N // 2), 80, 120, 150, 200):
        if time.process_time() >= deadline:
            break
        if N2 < 2:
            continue
        h_init = _resample(best_h, N2)
        h_init = np.maximum(h_init, 1e-12)
        h2 = polish(h_init, N2, deadline)
        c2 = _C(h2)
        if c2 < best_C:
            best_C, best_h = c2, h2.copy()

    # ---- local pattern search on log-h, exact C ----
    def pattern(h, deadline):
        h = np.maximum(h.astype(float), 1e-30)
        N = h.size
        c = _C(h)
        step = 0.02
        while time.process_time() < deadline and step > 1e-8:
            improved = False
            for i in range(N):
                if time.process_time() >= deadline:
                    return h, c
                old = h[i]
                for sgn in (1.0, -1.0):
                    h[i] = old * np.exp(sgn * step)
                    nc = _C(h)
                    if nc < c - 1e-15:
                        c = nc
                        old = h[i]
                        improved = True
                    else:
                        h[i] = old
            if not improved:
                step *= 0.5
        return h, c

    if time.process_time() < deadline:
        h3, c3 = pattern(best_h, deadline)
        if c3 < best_C:
            best_C, best_h = c3, h3.copy()

    if best_h is None:
        best_h = np.ones(50)
    return np.maximum(np.asarray(best_h, dtype=float), 0.0)

