    h = np.asarray(h, dtype=float)
    M = h.size
    if M == N:
        return h.copy()
    xi = np.linspace(0.0, 1.0, M)
    xo = np.linspace(0.0, 1.0, N)
    return np.interp(xo, xi, h)


def _gauss_kernel(sigma):
    if sigma <= 0:
        return np.array([1.0])
    r = int(np.ceil(3 * sigma))
    x = np.arange(-r, r + 1, dtype=float)
    g = np.exp(-0.5 * (x / sigma) ** 2)
    g /= g.sum()
    return g


def _make_fg(N, sigma):
    g = _gauss_kernel(sigma)
    rg = g.size // 2

    def make(beta):
        def fg(z):
            e = np.exp(z - z.max())
            s = e.sum()
            sh = e / s
            h = sh * N
            conv = np.convolve(h, h)
            if g.size > 1:
                conv_s = np.convolve(conv, g, 'same')
            else:
                conv_s = conv
            m = conv_s.max()
            w = np.exp(beta * (conv_s - m))
            wsum = w.sum()
            lse = m + np.log(wsum) / beta
            L = 2.0 * N * lse
            w = w / wsum
            # push w back through smoothing: correlate w with g
            if g.size > 1:
                w_back = np.convolve(w, g[::-1], 'same')
            else:
                w_back = w
            # d lse/dh_j = sum_k w_back_k * 2 h_{k-j}
            grad_conv = 2.0 * np.convolve(w_back, h[::-1])[N - 1:2 * N - 1]
            grad_h = 2.0 * N * grad_conv
            gz = N * sh * (grad_h - np.sum(grad_h * sh))
            return L, gz
        return fg
    return make


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    best_h = None
    best_C = np.inf

    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.ndim == 1 and hs.size > 0 and hs.sum() > 0 and np.all(np.isfinite(hs)):
            hs = np.maximum(hs, 0.0)
            c = _C(hs)
            if c < best_C:
                best_C, best_h = c, hs.copy()

    if best_h is None:
        N = 200
        x = -0.25 + (np.arange(N) + 0.5) / (2.0 * N)
        best_h = np.cos(2 * np.pi * x) ** 4 + 1e-3
        best_C = _C(best_h)

    N0 = best_h.size
    Ns = sorted(set([N0,
                     min(30000, max(50, N0 * 2)),
                     min(30000, max(50, N0 * 4))]))

    sigmas = [0, 1, 2, 3, 5]
    betas = [1e2, 1e3, 1e4, 1e5]

    for N in Ns:
        if time.process_time() >= deadline:
            break
        h_init = _resample(best_h, N)
        h_init = np.maximum(h_init, 1e-12)
        z0 = np.log(h_init)
        z0 = z0 - z0.mean()

        for sigma in sigmas:
            if time.process_time() >= deadline:
                break
            z = z0.copy()
            fg_maker = _make_fg(N, sigma)
            for beta in betas:
                if time.process_time() >= deadline:
                    break
                fg = fg_maker(beta)
                try:
                    res = minimize(fg, z, method='L-BFGS-B', jac=True,
                                   options={'maxiter': 500, 'ftol': 1e-16,
                                            'gtol': 1e-13})
                    z = res.x
                except Exception:
                    pass
                e = np.exp(z - z.max())
                h = e / e.sum() * N
                c = _C(h)
                if c < best_C:
                    best_C = c
                    best_h = h.copy()

    if best_h is None:
        best_h = np.ones(50)
    return np.maximum(np.asarray(best_h, dtype=float), 0.0)

