    if s <= 0 or not np.isfinite(s):
        return np.inf
    N = h.size
    m = np.max(np.convolve(h, h))
    return 2.0 * N * m / (s * s)


def _resample(h, N):
    h = np.asarray(h, dtype=float)
    M = h.size
    if M == N:
        return h.copy()
    xi = (np.arange(M) + 0.5) / M
    xo = (np.arange(N) + 0.5) / N
    return np.interp(xo, xi, h)


def _make_obj(N):
    def f_and_g(v):
        h = np.maximum(v, 0.0)
        s = h.sum()
        if s <= 0:
            return 1e10, np.zeros(N)
        conv = np.convolve(h, h)
        m = conv.max()
        idx = np.flatnonzero(conv >= m - 1e-15 * max(1.0, m))
        C = 2.0 * N * m / (s * s)
        mask = np.zeros(2 * N - 1)
        mask[idx] = 1.0 / idx.size
        gconv = 2.0 * np.convolve(mask, h[::-1])[N - 1:2 * N - 1]
        g = 2.0 * N / (s * s) * gconv - 4.0 * N * m / (s ** 3)
        g = np.where((h <= 0) & (g > 0), 0.0, g)
        return C, g
    return f_and_g


def _refine(h, N, deadline, maxiter=3000):
    fg = _make_obj(N)
    v = np.maximum(h, 1e-12)
    v = v / v.sum() * N
    try:
        res = minimize(fg, v, method='L-BFGS-B', jac=True,
                       options={'maxiter': maxiter, 'ftol': 1e-18, 'gtol': 1e-15})
        return np.maximum(res.x, 0.0)
    except Exception:
        return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.80

    best_h = None
    best_C = np.inf
    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.ndim == 1 and hs.size > 0 and hs.sum() > 0 and np.all(np.isfinite(hs)):
            hs = np.maximum(hs, 0.0)
            c = _C(hs)
            if c < best_C:
                best_C, best_h = c, hs.copy()

    if best_h is None:
        N = 200
        x = (np.arange(N) + 0.5) / N - 0.5
        best_h = np.cos(np.pi * x) ** 4 + 1e-3
        best_C = _C(best_h)

    N0 = best_h.size

    # Agressive refine at current N first
    if time.process_time() < deadline:
        h = _refine(best_h, N0, deadline, maxiter=5000)
        c = _C(h)
        if c < best_C:
            best_C, best_h = c, h.copy()

    # Key move: exhaustive N sweep around several scales, more N values
    Ns = []
    for N in (N0, N0 + 1, N0 - 1, N0 + 2, N0 - 2,
              max(2, N0 // 2), N0 * 2, N0 * 3, 60, 80, 99, 100, 101, 120,
              140, 150, 160, 180, 200, 220, 250, 280, 300, 350, 400, 500,
              600, 700, 800, 1000, 1200, 1500):
        if 2 <= N <= 30000 and N not in Ns:
            Ns.append(N)

    for N in Ns:
        if time.process_time() > deadline:
            break
        h_init = _resample(best_h, N)
        h_init = np.maximum(h_init, 1e-9)
        h_init = h_init / h_init.sum() * N
        h = _refine(h_init, N, deadline, maxiter=2000)
        c = _C(h)
        if c < best_C:
            best_C, best_h = c, h.copy()
            if time.process_time() < deadline:
                h2 = _refine(best_h, N, deadline, maxiter=3000)
                c2 = _C(h2)
                if c2 < best_C:
                    best_C, best_h = c2, h2.copy()

    # Random perturbations at best N and neighbor Ns
    if time.process_time() < deadline:
        rng = np.random.default_rng(12345)
        tries = 0
        while time.process_time() < deadline and tries < 30:
            tries += 1
            Nb = best_h.size
            # Try neighbors of best N too
            choices = [Nb, Nb + 1, Nb - 1]
            N = choices[tries % 3]
            if N < 2 or N > 30000:
                N = Nb
            base = _resample(best_h, N)
            amp = 5e-3 * (10 ** (tries % 4 - 2))
            vp = base * (1.0 + amp * rng.standard_normal(N))
            vp = np.maximum(vp, 0.0)
            if vp.sum() <= 0:
                continue
            h2 = _refine(vp, N, deadline, maxiter=1000)
            c2 = _C(h2)
            if c2 < best_C:
                best_C, best_h = c2, h2.copy()

    # Final polish
    if time.process_time() < deadline:
        N = best_h.size
        h = _refine(best_h, N, deadline, maxiter=5000)
        c = _C(h)
        if c < best_C:
            best_C, best_h = c, h

    return np.maximum(np.asarray(best_h, dtype=float), 0.0)

