                       constraints=cons,
                       options={'maxiter': maxiter, 'ftol': 1e-12})
        u = np.maximum(res.x[:K], 0.0)
        h = _mirror(u, N)
        if h.sum() <= 0:
            return None
        return h
    except Exception:
