        lse, w = _smooth_max(conv, beta)
        L = 2.0 * N * lse / (s * s)
        # gradient w.r.t. h of sum_k w_k conv_k, conv_k = sum_j h_j h_{k-j}
        # dconv_k/dh_j = 2 h_{k-j}; correlate w with h
        grad_conv = 2.0 * np.convolve(w, h[::-1])[N - 1:2 * N - 1]
        g = 2.0 * N / (s * s) * grad_conv - 2.0 * L / s
        return L, g
    return fg


