    s = h.sum()
    if s <= 0:
        return best_h, best_C
    h = h / s * N
    betas = [1e2, 1e3, 1e4, 1e5, 1e6, 1e7, 1e8, 1e9, 1e10]
    bounds = [(0.0, None)] * N
    cur = h
    for beta in betas:
        if time.process_time() >= deadline:
            break
        fg = _make_fg(N, beta)
        try:
            res = minimize(fg, cur, method='L-BFGS-B', jac=True, bounds=bounds,
                           options={'maxiter': 400, 'ftol': 1e-17, 'gtol': 1e-14})
            cur = np.maximum(res.x, 0.0)
            if cur.sum() <= 0:
                cur = h.copy()
        except Exception:
            pass
        c = _C(cur)
        if c < best_C:
            best_C = c
            best_h = cur.copy()
