        best_h = np.cos(2 * np.pi * x) ** 4 + 1e-3
        best_C = _C(best_h)

    # Polish at current N
    if time.process_time() < deadline:
        best_h, best_C = _polish_lbfgsb(best_h, best_h.size, deadline, best_h, best_C)

    # Progressive upsampling: 200 -> 400 -> 800 -> 1600 -> 3200 -> 6400
    N_cur = best_h.size
    for target in (400, 800, 1600, 3200, 6400, 12000):
        if time.process_time() >= deadline:
            break
        if target <= N_cur:
            continue
        h_up = _resample(best_h, target)
        h_up = np.maximum(h_up, 1e-12)
        h_up = h_up / h_up.sum() * target
        c = _C(h_up)
        if c < best_C:
            best_C = c
            best_h = h_up.copy()
        # quick L-BFGS-B at high beta then full polish
        if time.process_time() < deadline:
            best_h, best_C = _polish_lbfgsb(best_h, target, deadline, best_h, best_C)
            N_cur = target

    # Final exact-C pattern polish on log-heights for fine tuning
    if time.process_time() < deadline:
        h = np.maximum(best_h.copy(), 1e-30)
        N = h.size
        c = _C(h)
        steps = [1e-3, 5e-4, 2e-4, 1e-4, 5e-5, 2e-5, 1e-5, 5e-6, 2e-6, 1e-6]
        for s in steps:
            if time.process_time() >= deadline:
                break
            improved = False
            for i in range(N):
                if time.process_time() >= deadline:
                    break
                old = h[i]
                h[i] = old * np.exp(s)
                nc = _C(h)
                if nc < c - 1e-16:
                    c = nc
                    improved = True
                    if c < best_C:
                        best_C = c
                        best_h = h.copy()
                else:
                    h[i] = old
                h[i] = old * np.exp(-s)
                nc = _C(h)
                if nc < c - 1e-16:
                    c = nc
                    improved = True
                    if c < best_C:
                        best_C = c
                        best_h = h.copy()
                else:
                    h[i] = old
            if not improved:
                break

    return np.maximum(np.asarray(best_h, dtype=float), 0.0)

