        best_h = np.cos(2 * np.pi * x) ** 4 + 1e-3
        best_C = _C(best_h)

    # === Upsample: the optimum is smooth, higher resolution reduces
    #     staircase error of the step approximation ===
    N = best_h.size
    for N2 in (N * 2, N * 4, N * 8):
        if time.process_time() >= deadline:
            break
        if N2 > 20000:
            break
        h2 = _resample(best_h, N2)
        h2 = np.maximum(h2, 1e-12)
        h2 = h2 / h2.sum() * N2
        # quick p-norm polish at the new resolution
        for p in (16, 64, 256):
            if time.process_time() >= deadline:
                break
            fg = _pnorm_fg(N2, p)
            try:
                res = minimize(fg, h2, method='L-BFGS-B', jac=True,
                               bounds=[(0.0, None)] * N2,
                               options={'maxiter': 400, 'ftol': 1e-16})
                h2 = np.maximum(res.x, 0.0)
            except Exception:
                pass
        c = _C(h2)
        if c < best_C:
            best_C = c
            best_h = h2.copy()

    # === p-norm polish on winner ===
    N = best_h.size
    h = best_h.copy()
    h = h / h.sum() * N
    bounds = [(0.0, None)] * N
    for p in (8, 16, 32, 64, 128, 256, 512):
