import numpy as np
import time
from scipy.optimize import minimize, differential_evolution


def _C(h):
    s = h.sum()
    if s <= 0 or not np.isfinite(s):
        return np.inf
    N = h.size
    m = np.max(np.convolve(h, h))
    return 2.0 * N * m / (s * s)


def _resample(h, N):
    h = np.asarray(h, dtype=float)
    M = h.size
    if M == N:
        return h.copy()
    xi = np.linspace(0.0, 1.0, M)
    xo = np.linspace(0.0, 1.0, N)
    return np.interp(xo, xi, h)


def _smooth_max(conv, beta):
    m = conv.max()
    w = np.exp(beta * (conv - m))
    return m + np.log(w.sum()) / beta, w / w.sum()


def _fourier_h(params, N):
    """h_i = exp(sum_k a_k cos(2pi k x_i) + b_k sin(2pi k x_i)), K=6."""
    x = (np.arange(N) + 0.5) / N
    a = params[:6]
    b = params[6:12]
    logh = np.zeros(N)
    for k in range(6):
        kk = k + 1
        logh += a[k] * np.cos(2 * np.pi * kk * x) + b[k] * np.sin(2 * np.pi * kk * x)
    logh -= logh.max()
    return np.exp(logh)


def _fourier_C(params, N):
    h = _fourier_h(params, N)
    s = h.sum()
    if s <= 0 or not np.isfinite(s):
        return 1e30
    m = np.max(np.convolve(h, h))
    return 2.0 * N * m / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

