def _smooth_max(conv, beta):
    m = conv.max()
    w = np.exp(beta * (conv - m))
    return m + np.log(w.sum()) / beta, w / w.sum()


def _lbfgs_smooth(h0, betas, deadline, maxiter=400):
    """Polished smooth-max L-BFGS-B minimisation of C."""
    N = h0.size
    h = np.maximum(h0, 0.0)
    s = h.sum()
    if s <= 0:
        return None, np.inf
    h = h / s * N
    best_h = h.copy()
    best_C = _C(h)
    bounds = [(0.0, None)] * N

    def make_fg(N, beta):
        def fg(h):
            h = np.maximum(h, 0.0)
            s = h.sum()
            if s <= 0:
                return 1e30, np.zeros_like(h)
            conv = np.convolve(h, h)
            lse, w = _smooth_max(conv, beta)
            L = 2.0 * N * lse / (s * s)
            grad_conv = 2.0 * np.convolve(w, h[::-1])[N - 1:2 * N - 1]
            g = 2.0 * N / (s * s) * grad_conv - 2.0 * L / s
            return L, g
        return fg

    for beta in betas:
        if time.process_time() >= deadline:
            break
        fg = make_fg(N, beta)
        try:
            res = minimize(fg, h, method='L-BFGS-B', jac=True, bounds=bounds,
                           options={'maxiter': maxiter, 'ftol': 1e-17, 'gtol': 1e-14})
            h = np.maximum(res.x, 0.0)
        except Exception:
            pass
        c = _C(h)
        if c < best_C:
            best_C = c
            best_h = h.copy()
    return best_h, best_C


def _coordinate_polish(h, deadline, best_C):
    """Multiplicative coordinate descent on individual heights."""
    cur = h.copy()
    curC = _C(cur)
    if curC < best_C:
        best_C = curC
    N = cur.size
    deltas = [0.01, 0.005, 0.002, 0.001, 0.0005, 0.0002]
    while time.process_time() < deadline:
        improved = False
        for delta in deltas:
            if time.process_time() >= deadline:
                break
            up = np.exp(delta)
            dn = np.exp(-delta)
            for i in range(N):
                if time.process_time() >= deadline:
                    break
                cand = cur.copy()
                cand[i] *= up
                cC = _C(cand)
                if cC < curC - 1e-16:
                    cur, curC = cand, cC
                    improved = True
                    continue
                cand = cur.copy()
                cand[i] *= dn
                cC = _C(cand)
                if cC < curC - 1e-16:
                    cur, curC = cand, cC
                    improved = True
        if curC < best_C:
            best_C = curC
        if not improved:
            break
    return cur, best_C


