        hs = np.asarray(start, dtype=float)
        if hs.ndim == 1 and hs.size > 0 and hs.sum() > 0 and np.all(np.isfinite(hs)):
            hs = np.maximum(hs, 0.0)
            c = _C(hs)
            if c < best_C:
                best_C, best_h = c, hs.copy()

    if best_h is None:
        N = 200
        x = -0.25 + (np.arange(N) + 0.5) / (2.0 * N)
        best_h = np.cos(2 * np.pi * x) ** 4 + 1e-3
        best_C = _C(best_h)

    # Phase 1: refine the start at its own resolution with smooth-max L-BFGS.
    betas = [1e2, 1e3, 1e4, 1e5, 1e6, 1e7, 1e8]
    h1, c1 = _lbfgs_smooth(best_h, betas, deadline)
    if h1 is not None and c1 < best_C:
        best_C, best_h = c1, h1

    # Phase 2: progressive upsampling (finer resolution -> lower C).
    for N2 in (int(best_h.size * 2), int(best_h.size * 4), int(best_h.size * 8)):
        if time.process_time() >= deadline:
            break
        if N2 > 30000:
            break
        h2 = _resample(best_h, N2)
        h2 = np.maximum(h2, 1e-12)
        h2 = h2 / h2.sum() * N2
        h2, c2 = _lbfgs_smooth(h2, [1e5, 1e6, 1e7, 1e8], deadline, maxiter=250)
        if h2 is not None and c2 < best_C:
            best_C, best_h = c2, h2

    # Phase 3: coordinate polish on best resolution.
    if time.process_time() < deadline:
        hp, cp = _coordinate_polish(best_h, deadline, best_C)
        if cp < best_C:
            best_C, best_h = cp, hp

    return np.maximum(np.asarray(best_h, dtype=float), 0.0)

