    n = 1
    while n < 2 * N:
        n *= 2
    H = np.fft.rfft(h, n)
    conv = np.fft.irfft(H * H, n)[N - 1:2 * N - 1]
    return 2.0 * N * conv.max() / (s * s)


def _resample(h, N):
    h = np.asarray(h, dtype=float)
    M = h.size
    if M == N:
        return h.copy()
    xi = np.linspace(0.0, 1.0, M)
    xo = np.linspace(0.0, 1.0, N)
    return np.interp(xo, xi, h)


def _make_fg(N, beta):
    n = 1
    while n < 2 * N:
        n *= 2

    def fg(h):
        h = np.maximum(h, 0.0)
        s = h.sum()
        if s <= 0:
            return 1e30, np.zeros_like(h)
        H = np.fft.rfft(h, n)
        conv = np.fft.irfft(H * H, n)[N - 1:2 * N - 1]
        m = conv.max()
        w = np.exp(beta * (conv - m))
        wsum = w.sum()
        lse = m + np.log(wsum) / beta
        L = 2.0 * N * lse / (s * s)
        w = w / wsum
        W = np.fft.rfft(w, n)
        Hr = np.fft.rfft(h[::-1], n)
        corr = np.fft.irfft(W * Hr, n)
        grad_conv = 2.0 * corr[N - 1:2 * N - 1]
        g = 2.0 * N / (s * s) * grad_conv - 2.0 * L / s
        return L, g
    return fg


