        h = np.maximum(h, 1e-12)
        h = h / h.sum() * N
        bounds = [(0.0, None)] * N
        for beta in betas:
            if time.process_time() >= deadline:
                break
            fg = _make_fg(N, beta)
            try:
                res = minimize(fg, h, method='L-BFGS-B', jac=True, bounds=bounds,
                               options={'maxiter': maxiter, 'ftol': 1e-17,
                                        'gtol': 1e-14})
                h = np.maximum(res.x, 0.0)
            except Exception:
                pass
        return h

    N0 = best_h.size

    h = polish(best_h, N0, [1e2, 1e3, 1e4, 1e5, 1e6, 1e7, 1e8, 1e9])
    c = _C_fft(h)
    if c < best_C:
        best_C, best_h = c, h.copy()

    # Upsample progressively and polish each level; keep the best at any level.
    Ns = []
    for mult in (2, 3, 4, 6, 8, 12, 16, 24, 32):
        n = N0 * mult
        if n <= 30000:
            Ns.append(n)
        else:
            break

    for N in Ns:
        if time.process_time() >= deadline:
            break
        h2 = _resample(best_h, N)
        h2 = polish(h2, N, [1e4, 1e6, 1e8], maxiter=300)
        c = _C_fft(h2)
        if c < best_C:
            best_C, best_h = c, h2.copy()

    # Extra high-resolution polish at the current best.
    Nf = best_h.size
    if time.process_time() < deadline:
        hf = polish(best_h, Nf, [1e6, 1e8, 1e9, 1e10, 1e11], maxiter=800)
        c = _C_fft(hf)
        if c < best_C:
            best_C, best_h = c, hf.copy()

    # Try coarser resolutions too (sometimes fewer steps helps).
    if time.process_time() < deadline and Nf > 100:
        for f in (0.75, 0.5):
