import numpy as np
import time
from scipy.optimize import minimize, linprog


def _C(h):
    s = h.sum()
    if s <= 0 or not np.isfinite(s):
        return np.inf
    N = h.size
    m = np.max(np.convolve(h, h))
    return 2.0 * N * m / (s * s)


def _resample(h, N):
    h = np.asarray(h, dtype=float)
    M = h.size
    if M == N:
        return h.copy()
    xi = np.linspace(0.0, 1.0, M)
    xo = np.linspace(0.0, 1.0, N)
    return np.interp(xo, xi, h)


def _smooth_max(conv, beta):
    m = conv.max()
    w = np.exp(beta * (conv - m))
    return m + np.log(w.sum()) / beta, w / w.sum()


def _conv_jac(h):
    N = h.size
    K = 2 * N - 1
    J = np.zeros((K, N))
    for k in range(K):
        lo = max(0, k - (N - 1))
        hi = min(N - 1, k)
        if hi >= lo:
            J[k, lo:hi + 1] = 2.0 * h[k - np.arange(lo, hi + 1)]
    return J


def _slp_step(h, deadline, max_iter=40, trust=0.1):
    N = h.size
    h = np.maximum(h, 0.0)
    s = h.sum()
    if s <= 0:
        return h
    h = h / s * N
    best_h = h.copy()
    best_C = _C(h)

    for it in range(max_iter):
        if time.process_time() >= deadline:
            break
        conv = np.convolve(h, h)
        J = _conv_jac(h)
        K = conv.size
        c_obj = np.zeros(N + 1)
        c_obj[-1] = 1.0
        A_ub = np.hstack([J, -np.ones((K, 1))])
        b_ub = -conv
        A_eq = np.zeros((1, N + 1))
        A_eq[0, :N] = 1.0
        b_eq = np.array([0.0])
        hmax = max(h.max(), 1e-12)
        dmax = trust * hmax
        bounds = [(-min(h[i], dmax), dmax) for i in range(N)] + [(None, None)]
        try:
            res = linprog(c_obj, A_ub=A_ub, b_ub=b_ub, A_eq=A_eq, b_eq=b_eq,
                          bounds=bounds, method='highs')
        except Exception:
            break
        if not res.success:
            break
        delta = res.x[:N]
        step = 1.0
        improved = False
        for _ in range(20):
            h_try = np.maximum(h + step * delta, 0.0)
            if h_try.sum() <= 0:
                step *= 0.5
                continue
            c_try = _C(h_try)
            if c_try < best_C - 1e-16:
                h = h_try
                best_C = c_try
                best_h = h.copy()
                improved = True
                break
            step *= 0.5
        if not improved:
            if trust > 1e-4:
                trust *= 0.5
                continue
            else:
                break
    return best_h


def _make_fg(N, beta):
    def fg(h):
        h = np.maximum(h, 0.0)
        s = h.sum()
        if s <= 0:
            return 1e30, np.zeros_like(h)
        conv = np.convolve(h, h)
        lse, w = _smooth_max(conv, beta)
        L = 2.0 * N * lse / (s * s)
        grad_conv = 2.0 * np.convolve(w, h[::-1])[N - 1:2 * N - 1]
        g = 2.0 * N / (s * s) * grad_conv - 2.0 * L / s
        return L, g
    return fg


def _polish(h, best_C, best_h, deadline, betas=(1e4, 1e6, 1e8, 1e10)):
    h = np.maximum(h, 0.0)
    if h.sum() <= 0:
        return best_C, best_h
    N = h.size
    h = h / h.sum() * N
    for beta in betas:
        if time.process_time() >= deadline:
            break
        fg = _make_fg(N, beta)
        try:
            res = minimize(fg, h, method='L-BFGS-B', jac=True,
                           bounds=[(0.0, None)] * N,
                           options={'maxiter': 400, 'ftol': 1e-17, 'gtol': 1e-14})
            h = np.maximum(res.x, 0.0)
        except Exception:
            pass
        c = _C(h)
        if c < best_C:
            best_C = c
            best_h = h.copy()
    return best_C, best_h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.80

    best_h = None
    best_C = np.inf

    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.ndim == 1 and hs.size > 0 and hs.sum() > 0 and np.all(np.isfinite(hs)):
            hs = np.maximum(hs, 0.0)
            c = _C(hs)
            if c < best_C:
                best_C, best_h = c, hs.copy()

    if best_h is None:
        N = 200
        x = -0.25 + (np.arange(N) + 0.5) / (2.0 * N)
        best_h = np.cos(2 * np.pi * x) ** 4 + 1e-3
        best_C = _C(best_h)

    orig_h = best_h.copy()
    orig_C = best_C

    # === Experiment: solve at N=1600, downsample to N=400 ===
    N_fine = 1600
    N_coarse = 400

    if time.process_time() < deadline:
        h_fine = np.maximum(_resample(orig_h, N_fine), 0.0)
        if h_fine.sum() > 0:
            h_fine = h_fine / h_fine.sum() * N_fine
            # Full-step SLP (trust=1.0 effectively removes trust bounds)
            h_fine = _slp_step(h_fine, deadline, max_iter=40, trust=1.0)
            c = _C(h_fine)
            if c < best_C:
                best_C, best_h = c, h_fine.copy()
            if time.process_time() < deadline:
                c2, h2 = _polish(h_fine, c, h_fine, deadline,
                                 betas=(1e4, 1e6, 1e8, 1e10))
                if c2 < best_C:
                    best_C, best_h = c2, h2.copy()
                h_fine = h2 if c2 <= c else h_fine

            # Downsample to N=400
            if time.process_time() < deadline:
                h_ds = np.maximum(_resample(h_fine, N_coarse), 0.0)
                if h_ds.sum() > 0:
                    h_ds = h_ds / h_ds.sum() * N_coarse
