    M = h.size
    if M == N:
        return h.copy()
    xi = np.linspace(0.0, 1.0, M)
    xo = np.linspace(0.0, 1.0, N)
    return np.interp(xo, xi, h)


def _make_fg(N, beta):
    def fg(h):
        h = np.maximum(h, 0.0)
        s = h.sum()
        if s <= 0:
            return 1e30, np.zeros_like(h)
        conv = np.convolve(h, h)
        m = conv.max()
        w = np.exp(beta * (conv - m))
        lse = m + np.log(w.sum()) / beta
        w /= w.sum()
        L = 2.0 * N * lse / (s * s)
        # gradient of lse wrt h
        gc = 2.0 * np.convolve(w, h[::-1])[N - 1:2 * N - 1]
        g = 2.0 * N / (s * s) * gc - 2.0 * L / s
        return L, g
    return fg


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    best_h = None
    best_C = np.inf

    if start is not None:
        hs = np.asarray(start, dtype=float).ravel()
        if hs.size > 0 and hs.sum() > 0 and np.all(np.isfinite(hs)):
            hs = np.maximum(hs, 0.0)
            c = _C(hs)
            if c < best_C:
                best_C, best_h = c, hs.copy()

    if best_h is None:
        N = 80
        x = -0.25 + (np.arange(N) + 0.5) / (2.0 * N)
        best_h = np.cos(2 * np.pi * x) ** 4 + 1e-3
        best_C = _C(best_h)

    # Smooth-max polish at the starting resolution with progressive betas.
    def polish(h, betas):
        nonlocal best_h, best_C
        h = np.maximum(h, 0.0)
        if h.sum() <= 0:
            return
        N = h.size
        h = h / h.sum() * N
        for beta in betas:
            if time.process_time() >= deadline:
                return
            fg = _make_fg(N, beta)
            try:
                res = minimize(fg, h, method='L-BFGS-B', jac=True,
                               bounds=[(0.0, None)] * N,
                               options={'maxiter': 500, 'ftol': 1e-18, 'gtol': 1e-14})
                h = np.maximum(res.x, 0.0)
            except Exception:
                pass
            c = _C(h)
            if c < best_C:
                best_C, best_h = c, h.copy()

    # Multi-scale refinement: polish at current N, then upsample+polish.
    betas = (1e3, 1e5, 1e7, 1e9, 1e11)
    polish(best_h, betas)

    for mult in (2, 2, 2):
        if time.process_time() >= deadline:
            break
        N2 = best_h.size * mult
        if N2 > 30000:
            break
        h2 = np.maximum(_resample(best_h, N2), 1e-12)
        polish(h2, betas)

    return np.maximum(np.asarray(best_h, dtype=float), 0.0)

