import numpy as np
import time
from scipy.optimize import minimize, linprog, least_squares
from scipy.signal import fftconvolve


def _C(h):
    s = h.sum()
    if s <= 0 or not np.isfinite(s):
        return np.inf
    N = h.size
    m = np.max(np.convolve(h, h))
    return 2.0 * N * m / (s * s)


def _fft_conv(h):
    return fftconvolve(h, h, mode='full')


def _C_fft(h):
    s = h.sum()
    if s <= 0 or not np.isfinite(s):
        return np.inf
    N = h.size
    m = np.max(_fft_conv(h))
    return 2.0 * N * m / (s * s)


def _resample(h, N):
    h = np.asarray(h, dtype=float)
    M = h.size
    if M == N:
        return h.copy()
    xi = np.linspace(0.0, 1.0, M)
    xo = np.linspace(0.0, 1.0, N)
    return np.interp(xo, xi, h)


def _smooth_max(conv, beta):
    m = conv.max()
    w = np.exp(beta * (conv - m))
    return m + np.log(w.sum()) / beta, w / w.sum()


def _conv_jac(h):
    N = h.size
    K = 2 * N - 1
    J = np.zeros((K, N))
    for k in range(K):
        lo = max(0, k - (N - 1))
        hi = min(N - 1, k)
        if hi >= lo:
            J[k, lo:hi + 1] = 2.0 * h[k - np.arange(lo, hi + 1)]
    return J


def _slp_step(h, deadline, max_iter=40, trust=0.1):
    N = h.size
    h = np.maximum(h, 0.0)
    s = h.sum()
    if s <= 0:
        return h
    h = h / s * N
    best_h = h.copy()
    best_C = _C(h)

    for it in range(max_iter):
        if time.process_time() >= deadline:
            break
        conv = np.convolve(h, h)
        J = _conv_jac(h)
        K = conv.size
        c_obj = np.zeros(N + 1)
        c_obj[-1] = 1.0
        A_ub = np.hstack([J, -np.ones((K, 1))])
        b_ub = -conv
        A_eq = np.zeros((1, N + 1))
        A_eq[0, :N] = 1.0
        b_eq = np.array([0.0])
        hmax = max(h.max(), 1e-12)
        dmax = trust * hmax
        bounds = [(-min(h[i], dmax), dmax) for i in range(N)] + [(None, None)]
        try:
            res = linprog(c_obj, A_ub=A_ub, b_ub=b_ub, A_eq=A_eq, b_eq=b_eq,
                          bounds=bounds, method='highs')
        except Exception:
            break
        if not res.success:
            break
        delta = res.x[:N]
        step = 1.0
        improved = False
        for _ in range(20):
            h_try = np.maximum(h + step * delta, 0.0)
            if h_try.sum() <= 0:
                step *= 0.5
                continue
            c_try = _C(h_try)
            if c_try < best_C - 1e-16:
                h = h_try
                best_C = c_try
                best_h = h.copy()
                improved = True
                break
            step *= 0.5
        if not improved:
            if trust > 1e-4:
                trust *= 0.5
                continue
            else:
                break
    return best_h


def _make_fg(N, beta, use_fft=False):
    def fg(h):
        h = np.maximum(h, 0.0)
        s = h.sum()
        if s <= 0:
            return 1e30, np.zeros_like(h)
        if use_fft:
            conv = _fft_conv(h)
        else:
            conv = np.convolve(h, h)
        lse, w = _smooth_max(conv, beta)
        L = 2.0 * N * lse / (s * s)
        if use_fft:
            grad_conv = 2.0 * fftconvolve(w, h[::-1], mode='full')[N - 1:2 * N - 1]
        else:
            grad_conv = 2.0 * np.convolve(w, h[::-1])[N - 1:2 * N - 1]
        g = 2.0 * N / (s * s) * grad_conv - 2.0 * L / s
        return L, g
    return fg


def _polish(h, best_C, best_h, deadline, betas=(1e4, 1e6, 1e8, 1e10)):
    h = np.maximum(h, 0.0)
    if h.sum() <= 0:
        return best_C, best_h
    N = h.size
    h = h / h.sum() * N
    for beta in betas:
        if time.process_time() >= deadline:
            break
        fg = _make_fg(N, beta)
        try:
            res = minimize(fg, h, method='L-BFGS-B', jac=True,
                           bounds=[(0.0, None)] * N,
                           options={'maxiter': 400, 'ftol': 1e-17, 'gtol': 1e-14})
            h = np.maximum(res.x, 0.0)
        except Exception:
            pass
        c = _C(h)
        if c < best_C:
            best_C = c
            best_h = h.copy()
    return best_C, best_h


def _tilt_step(h, deadline, max_iter=60):
    N = h.size
    h = np.maximum(h, 0.0)
    s = h.sum()
    if s <= 0:
        return h
    h = h / s * N
    best_h = h.copy()
    best_C = _C(h)

    for it in range(max_iter):
        if time.process_time() >= deadline:
            break
        conv = np.convolve(h, h)
        cmax = conv.max()
        band = 1e-6 * max(cmax, 1e-30)
        active = np.where(conv >= cmax - band)[0]
        if active.size < 2:
            M = min(20, conv.size)
            active = np.argpartition(conv, conv.size - M)[conv.size - M:]
            active.sort()
        w = np.zeros_like(conv)
        w[active] = 1.0
        w /= w.sum()
        grad = 2.0 * np.convolve(w, h[::-1])[N - 1:2 * N - 1]
        grad = grad - grad.mean()
        scale = np.max(np.abs(grad)) + 1e-30
        step = 0.05
        improved = False
        for _ in range(25):
            h_try = h - step * (grad / scale) * h
            h_try = np.maximum(h_try, 0.0)
            if h_try.sum() <= 0:
                step *= 0.5
                continue
            c_try = _C(h_try)
            if c_try < best_C - 1e-16:
                h = h_try
                best_C = c_try
                best_h = h.copy()
                improved = True
                break
            step *= 0.5
        if not improved:
            break
    return best_h


def _active_set_ls(h, deadline, max_nfev=300):
    """Nonlinear least-squares: equalize active convolution knots and fix sum."""
    h = np.maximum(np.asarray(h, dtype=float), 0.0)
    N = h.size
    s = h.sum()
    if s <= 0:
        return h, np.inf
    h = h / s * N
    conv = np.convolve(h, h)
    cmax = conv.max()
    P = np.where(h > 1e-12)[0]
    if P.size == 0:
        return h, _C(h)
    thr = cmax - 1e-9 * max(cmax, 1e-30)
    A = list(np.where(conv >= thr)[0])
    target = min(max(P.size - 1, 1), 2 * P.size)
    if len(A) < target:
        order = np.argsort(conv)[::-1]
        A_set = set(A)
        for idx in order:
            if idx not in A_set:
                A.append(int(idx))
                A_set.add(int(idx))
            if len(A) >= target:
                break
    A = np.array(sorted(A), dtype=int)
    nP = P.size
    Pset = set(P.tolist())

    idx_lists = []
    for k in A:
        lo = max(0, k - (N - 1))
        hi = min(N - 1, k)
        pairs = [(i, k - i) for i in range(lo, hi + 1)
                 if i in Pset and (k - i) in Pset]
        idx_lists.append(pairs)

    pos = {int(g): j for j, g in enumerate(P)}

    def residuals(x):
        hP = x[:nP]
        M = x[nP]
        r = np.empty(A.size + 1)
        for a, pairs in enumerate(idx_lists):
            tot = 0.0
            for i, j in pairs:
                tot += hP[pos[i]] * hP[pos[j]]
            r[a] = tot - M
        r[-1] = hP.sum() - N
        return r

    x0 = np.empty(nP + 1)
    x0[:nP] = h[P]
    x0[nP] = cmax
    lb = np.zeros(nP + 1)
    ub = np.full(nP + 1, np.inf)

    if time.process_time() >= deadline:
        return h, _C(h)
