                           options={'maxiter': 200, 'ftol': 1e-17, 'gtol': 1e-13})
            h2 = np.maximum(res.x, 0.0)
            c = _C(h2)
            if c < best_C:
                best_C, best_h = c, h2.copy()
        except Exception:
            pass

    # === NEW EXPERIMENT: FFT-based high-resolution (N=30000) polish ===
    if time.process_time() < deadline:
        N_hi = 30000
        h_hi = np.maximum(_resample(best_h, N_hi), 1e-12)
        s = h_hi.sum()
        if s > 0:
            h_hi = h_hi / s * N_hi
            c_hi = _C_fft(h_hi)
            if c_hi < best_C:
                best_C, best_h = c_hi, h_hi.copy()
            if time.process_time() < deadline:
                fg = _make_fg(N_hi, 1e6, use_fft=True)
                try:
                    res = minimize(fg, h_hi, method='L-BFGS-B', jac=True,
                                   bounds=[(0.0, None)] * N_hi,
                                   options={'maxiter': 30, 'ftol': 1e-17,
                                            'gtol': 1e-13})
                    h_new = np.maximum(res.x, 0.0)
                    c_new = _C_fft(h_new)
                    if c_new < best_C:
                        best_C, best_h = c_new, h_new.copy()
                except Exception:
                    pass

    return np.maximum(np.asarray(best_h, dtype=float), 0.0)

