        best_h = np.cos(2 * np.pi * x) ** 4 + 1e-3
        best_C = _C(best_h)

    # Push toward smaller discretisation error: immediately upsample the start
    # to a moderately large N and polish there, since the true optimum is smooth.
    # Small N polishing wastes time; large N captures the continuous optimum.
    Ns = []
    N = best_h.size
    for N2 in (N, 1200, 2400, 4800, 9600, 16000, 24000, 30000):
        if N2 >= N and N2 not in Ns and N2 <= 30000:
            Ns.append(N2)

    betas_hi = [1e2, 1e3, 1e4, 1e5, 1e6, 1e7, 1e8, 1e9, 1e10]

    for N2 in Ns:
        if time.process_time() >= deadline:
            break
        h2 = _resample(best_h, N2)
        h2 = np.maximum(h2, 1e-12)
        h2 = _polish(h2, deadline, betas_hi, maxiter=200)
