import numpy as np
import time
from scipy.optimize import minimize, linprog
from scipy.signal import fftconvolve


def _C(h):
    s = h.sum()
    if s <= 0 or not np.isfinite(s):
        return np.inf
    N = h.size
    m = np.max(np.convolve(h, h))
    return 2.0 * N * m / (s * s)


def _C_fft(h):
    s = h.sum()
    if s <= 0 or not np.isfinite(s):
        return np.inf
    N = h.size
    m = np.max(fftconvolve(h, h, mode='full'))
    return 2.0 * N * m / (s * s)


def _resample(h, N):
    h = np.asarray(h, dtype=float)
    M = h.size
    if M == N:
        return h.copy()
    xi = np.linspace(0.0, 1.0, M)
    xo = np.linspace(0.0, 1.0, N)
    return np.interp(xo, xi, h)


def _smooth_max(conv, beta):
    m = conv.max()
    w = np.exp(beta * (conv - m))
    return m + np.log(w.sum()) / beta, w / w.sum()


def _make_fg(N, beta, use_fft=False):
    def fg(h):
        h = np.maximum(h, 0.0)
        s = h.sum()
        if s <= 0:
            return 1e30, np.zeros_like(h)
        if use_fft:
            conv = fftconvolve(h, h, mode='full')
        else:
            conv = np.convolve(h, h)
        lse, w = _smooth_max(conv, beta)
        L = 2.0 * N * lse / (s * s)
        if use_fft:
            grad_conv = 2.0 * fftconvolve(w, h[::-1], mode='full')[N - 1:2 * N - 1]
        else:
            grad_conv = 2.0 * np.convolve(w, h[::-1])[N - 1:2 * N - 1]
        g = 2.0 * N / (s * s) * grad_conv - 2.0 * L / s
        return L, g
    return fg


def _polish(h, best_C, best_h, deadline, betas=(1e4, 1e6, 1e8, 1e10)):
    h = np.maximum(h, 0.0)
    if h.sum() <= 0:
        return best_C, best_h
    N = h.size
    h = h / h.sum() * N
    use_fft = N > 2000
    for beta in betas:
        if time.process_time() >= deadline:
            break
        fg = _make_fg(N, beta, use_fft)
        try:
            res = minimize(fg, h, method='L-BFGS-B', jac=True,
                           bounds=[(0.0, None)] * N,
                           options={'maxiter': 400, 'ftol': 1e-17, 'gtol': 1e-14})
            h = np.maximum(res.x, 0.0)
        except Exception:
            pass
        c = _C_fft(h) if use_fft else _C(h)
        if c < best_C:
            best_C = c
            best_h = h.copy()
    return best_C, best_h


def _tilt_step(h, deadline, max_iter=60):
    N = h.size
    h = np.maximum(h, 0.0)
    s = h.sum()
    if s <= 0:
        return h
    h = h / s * N
    best_h = h.copy()
    best_C = _C(h)
    use_fft = N > 2000

    for it in range(max_iter):
        if time.process_time() >= deadline:
            break
        if use_fft:
            conv = fftconvolve(h, h, mode='full')
            grad = 2.0 * fftconvolve
        else:
            conv = np.convolve(h, h)
        cmax = conv.max()
        band = 1e-6 * max(cmax, 1e-30)
        active = np.where(conv >= cmax - band)[0]
        if active.size < 2:
            M = min(20, conv.size)
            active = np.argpartition(conv, conv.size - M)[conv.size - M:]
            active.sort()
        w = np.zeros_like(conv)
        w[active] = 1.0
        w /= w.sum()
        if use_fft:
            gc = 2.0 * fftconvolve(w, h[::-1], mode='full')[N - 1:2 * N - 1]
        else:
            gc = 2.0 * np.convolve(w, h[::-1])[N - 1:2 * N - 1]
        grad = gc - gc.mean()
        scale = np.max(np.abs(grad)) + 1e-30
        step = 0.05
        improved = False
        for _ in range(25):
            h_try = np.maximum(h - step * (grad / scale) * h, 0.0)
            if h_try.sum() <= 0:
                step *= 0.5
                continue
            c_try = _C_fft(h_try) if use_fft else _C(h_try)
            if c_try < best_C - 1e-16:
                h = h_try
                best_C = c_try
                best_h = h.copy()
                improved = True
                break
            step *= 0.5
        if not improved:
            break
    return best_h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    best_h = None
    best_C = np.inf

    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.ndim == 1 and hs.size > 0 and hs.sum() > 0 and np.all(np.isfinite(hs)):
            hs = np.maximum(hs, 0.0)
            c = _C(hs)
            if c < best_C:
                best_C, best_h = c, hs.copy()

    if best_h is None:
        N = 400
        x = -0.25 + (np.arange(N) + 0.5) / (2.0 * N)
        best_h = np.cos(2 * np.pi * x) ** 4 + 1e-3
        best_C = _C(best_h)

    # Multi-scale upsampling + smooth-max polish. Start at start's N, go up.
    # Each scale: resample up, polish with smooth max, tilt, keep best.
    scales = [best_h.size]
    s = best_h.size
    while s < 30000:
        s = min(s * 2, 30000)
        scales.append(s)

    for N in scales:
        if time.process_time() >= deadline:
            break
        h = np.maximum(_resample(best_h, N), 0.0)
        if h.sum() <= 0:
            continue
        h = h / h.sum() * N
        # coarse smooth-max at this scale
        c0 = _C_fft(h) if N > 2000 else _C(h)
        if c0 < best_C:
            # only adopt if genuinely better (avoid noise from resampling)
            if N <= best_h.size or c0 < best_C - 1e-12:
                best_C, best_h = c0, h.copy()
        # polish
        c_p, h_p = _polish(h, best_C, best_h, deadline)
        if c_p < best_C:
            best_C, best_h = c_p, h_p.copy()
        # tilt
        if time.process_time() < deadline:
            h_t = _tilt_step(best_h.copy(), deadline, max_iter=40)
            c_t = _C_fft(h_t) if h_t.size > 2000 else _C(h_t)
            if c_t < best_C:
                best_C, best_h = c_t, h_t.copy()

    return np.maximum(np.asarray(best_h, dtype=float), 0.0)

