def _conv_jac(h):
    N = h.size
    K = 2 * N - 1
    J = np.zeros((K, N))
    for k in range(K):
        lo = max(0, k - (N - 1))
        hi = min(N - 1, k)
        if hi >= lo:
            J[k, lo:hi + 1] = 2.0 * h[k - np.arange(lo, hi + 1)]
    return J


def _make_fg(N, beta):
    def fg(h):
        h = np.maximum(h, 0.0)
        s = h.sum()
        if s <= 0:
            return 1e30, np.zeros_like(h)
        conv = np.convolve(h, h)
        lse, w = _smooth_max(conv, beta)
        L = 2.0 * N * lse / (s * s)
        grad_conv = 2.0 * np.convolve(w, h[::-1])[N - 1:2 * N - 1]
        g = 2.0 * N / (s * s) * grad_conv - 2.0 * L / s
        return L, g
    return fg


def _polish(h, best_C, best_h, deadline, betas=(1e4, 1e6, 1e8, 1e10)):
    h = np.maximum(h, 0.0)
    if h.sum() <= 0:
        return best_C, best_h
    N = h.size
    h = h / h.sum() * N
    for beta in betas:
        if time.process_time() >= deadline:
            break
        fg = _make_fg(N, beta)
        try:
            res = minimize(fg, h, method='L-BFGS-B', jac=True,
                           bounds=[(0.0, None)] * N,
                           options={'maxiter': 400, 'ftol': 1e-17, 'gtol': 1e-14})
            h = np.maximum(res.x, 0.0)
        except Exception:
            pass
        c = _C(h)
        if c < best_C:
            best_C = c
            best_h = h.copy()
    return best_C, best_h


def _tilt_step(h, deadline, max_iter=60):
    N = h.size
    h = np.maximum(h, 0.0)
    s = h.sum()
    if s <= 0:
        return h
    h = h / s * N
    best_h = h.copy()
    best_C = _C(h)

    for it in range(max_iter):
        if time.process_time() >= deadline:
            break
        conv = np.convolve(h, h)
        cmax = conv.max()
        band = 1e-6 * max(cmax, 1e-30)
        active = np.where(conv >= cmax - band)[0]
        if active.size < 2:
            M = min(20, conv.size)
            active = np.argpartition(conv, conv.size - M)[conv.size - M:]
            active.sort()
        w = np.zeros_like(conv)
        w[active] = 1.0
        w /= w.sum()
        grad = 2.0 * np.convolve(w, h[::-1])[N - 1:2 * N - 1]
        grad = grad - grad.mean()
        scale = np.max(np.abs(grad)) + 1e-30
        step = 0.05
        improved = False
        for _ in range(25):
            h_try = h - step * (grad / scale) * h
            h_try = np.maximum(h_try, 0.0)
            if h_try.sum() <= 0:
                step *= 0.5
                continue
            c_try = _C(h_try)
            if c_try < best_C - 1e-16:
                h = h_try
                best_C = c_try
                best_h = h.copy()
                improved = True
                break
            step *= 0.5
        if not improved:
            break
    return best_h


def _active_set_ls(h, deadline, max_nfev=300):
    h = np.maximum(np.asarray(h, dtype=float), 0.0)
    N = h.size
    s = h.sum()
    if s <= 0:
        return h, np.inf
    h = h / s * N
    conv = np.convolve(h, h)
    cmax = conv.max()
    P = np.where(h > 1e-12)[0]
    if P.size == 0:
        return h, _C(h)
    thr = cmax - 1e-9 * max(cmax, 1e-30)
    A = list(np.where(conv >= thr)[0])
    target = min(max(P.size - 1, 1), 2 * P.size)
    if len(A) < target:
        order = np.argsort(conv)[::-1]
        A_set = set(A)
        for idx in order:
            if idx not in A_set:
                A.append(int(idx))
                A_set.add(int(idx))
            if len(A) >= target:
                break
    A = np.array(sorted(A), dtype=int)
    nP = P.size
    Pset = set(P.tolist())

    idx_lists = []
    for k in A:
        lo = max(0, k - (N - 1))
        hi = min(N - 1, k)
        pairs = [(i, k - i) for i in range(lo, hi + 1)
                 if i in Pset and (k - i) in Pset]
        idx_lists.append(pairs)

    pos = {int(g): j for j, g in enumerate(P)}

    def residuals(x):
        hP = x[:nP]
        M = x[nP]
        r = np.empty(A.size + 1)
        for a, pairs in enumerate(idx_lists):
            tot = 0.0
            for i, j in pairs:
                tot += hP[pos[i]] * hP[pos[j]]
            r[a] = tot - M
        r[-1] = hP.sum() - N
        return r

    x0 = np.empty(nP + 1)
    x0[:nP] = h[P]
    x0[nP] = cmax
    lb = np.zeros(nP + 1)
    ub = np.full(nP + 1, np.inf)

    if time.process_time() >= deadline:
        return h, _C(h)
    try:
        res = least_squares(residuals, x0, bounds=(lb, ub),
                            max_nfev=max_nfev, xtol=1e-15, ftol=1e-15,
                            gtol=1e-15)
        hP = np.maximum(res.x[:nP], 0.0)
        h_new = np.zeros(N)
        h_new[P] = hP
        if h_new.sum() > 0:
            return h_new, _C(h_new)
    except Exception:
        pass
    return h, _C(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    best_h = None
    best_C = np.inf

    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.ndim == 1 and hs.size > 0 and hs.sum() > 0 and np.all(np.isfinite(hs)):
            hs = np.maximum(hs, 0.0)
            c = _C(hs)
            if c < best_C:
                best_C, best_h = c, hs.copy()

    if best_h is None:
        N = 200
        x = -0.25 + (np.arange(N) + 0.5) / (2.0 * N)
        best_h = np.cos(2 * np.pi * x) ** 4 + 1e-3
        best_C = _C(best_h)

    # === Active-set least-squares at start resolution ===
    if time.process_time() < deadline:
        N0 = best_h.size
        h0 = np.maximum(best_h.copy(), 0.0)
        if h0.sum() > 0:
            h0 = h0 / h0.sum() * N0
            h_ls, c_ls = _active_set_ls(h0, deadline, max_nfev=400)
            if c_ls < best_C:
                best_C, best_h = c_ls, h_ls.copy()
            if time.process_time() < deadline:
                c_p, h_p = _polish(h_ls, c_ls, h_ls, deadline)
                if c_p < best_C:
                    best_C, best_h = c_p, h_p.copy()

    # === Tilt-based descent ===
    if time.process_time() < deadline:
        h_tilt = _tilt_step(best_h.copy(), deadline, max_iter=80)
        c = _C(h_tilt)
        if c < best_C:
            best_C, best_h = c, h_tilt.copy()

    # === Active-set LS again after tilt ===
    if time.process_time() < deadline:
        N0 = best_h.size
        h0 = np.maximum(best_h.copy(), 0.0)
        if h0.sum() > 0:
            h0 = h0 / h0.sum() * N0
            h_ls, c_ls = _active_set_ls(h0, deadline, max_nfev=400)
            if c_ls < best_C:
                best_C, best_h = c_ls, h_ls.copy()
            if time.process_time() < deadline:
                c_p, h_p = _polish(h_ls, c_ls, h_ls, deadline)
                if c_p < best_C:
                    best_C, best_h = c_p, h_p.copy()

    # === Smooth-max polish ===
    if time.process_time() < deadline:
        best_C, best_h = _polish(best_h, best_C, best_h, deadline)

    # === Tilt again ===
    if time.process_time() < deadline:
        h_tilt = _tilt_step(best_h.copy(), deadline, max_iter=80)
        c = _C(h_tilt)
        if c < best_C:
            best_C, best_h = c, h_tilt.copy()

    # === Final active-set LS + polish ===
    if time.process_time() < deadline:
        N0 = best_h.size
        h0 = np.maximum(best_h.copy(), 0.0)
        if h0.sum() > 0:
            h0 = h0 / h0.sum() * N0
            h_ls, c_ls = _active_set_ls(h0, deadline, max_nfev=400)
            if c_ls < best_C:
                best_C, best_h = c_ls, h_ls.copy()
            if time.process_time() < deadline:
                c_p, h_p = _polish(h_ls, c_ls, h_ls, deadline)
                if c_p < best_C:
                    best_C, best_h = c_p, h_p.copy()

    return np.maximum(np.asarray(best_h, dtype=float), 0.0)

import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0 or not np.isfinite(s):
        return np.inf
    N = h.size
    m = np.max(np.convolve(h, h))
    return 2.0 * N * m / (s * s)


def _resample(h, N):
    h = np.asarray(h, dtype=float)
    M = h.size
    if M == N:
        return h.copy()
    xi = np.linspace(0.0, 1.0, M)
    xo = np.linspace(0.0, 1.0, N)
    return np.interp(xo, xi, h)


def _softmax_stats(conv, beta):
    m = conv.max()
    z = beta * (conv - m)
    w = np.exp(z)
    Z = w.sum()
    lse = m + np.log(Z) / beta
    return lse, w / Z


def _fg_factory(N, beta):
    def fg(h):
        h = np.maximum(h, 0.0)
        s = h.sum()
        if s <= 0:
            return 1e30, np.zeros_like(h)
        conv = np.convolve(h, h)
        lse, w = _softmax_stats(conv, beta)
        L = 2.0 * N * lse / (s * s)
        gc = 2.0 * np.convolve(w, h[::-1])[N - 1:2 * N - 1]
        g = (2.0 * N / (s * s)) * gc - (2.0 * L / s)
        return L, g
    return fg


def _polish(h, deadline, betas, maxiter=300):
    h = h.copy()
    s = h.sum()
    if s <= 0:
        return h
    h = h / s * h.size
    bounds = [(0.0, None)] * h.size
    for beta in betas:
        if time.process_time() >= deadline:
            break
        fg = _fg_factory(h.size, beta)
        try:
            res = minimize(fg, h, method='L-BFGS-B', jac=True, bounds=bounds,
                           options={'maxiter': maxiter, 'ftol': 1e-16,
                                    'gtol': 1e-13, 'maxcor': 30})
            h = np.maximum(res.x, 0.0)
        except Exception:
            pass
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.82

    best_h = None
    best_C = np.inf

    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.ndim == 1 and hs.size > 0 and hs.sum() > 0 and np.all(np.isfinite(hs)):
            hs = np.maximum(hs, 0.0)
            c = _C(hs)
            if c < best_C:
                best_C, best_h = c, hs.copy()

    if best_h is None:
        N = 400
        x = -0.25 + (np.arange(N) + 0.5) / (2.0 * N)
        best_h = np.cos(2 * np.pi * x) ** 4 + 1e-3
        best_C = _C(best_h)

    Ns = []
    N = best_h.size
    for N2 in (N, 800, 1600, 3200, 6400, 12000, 20000, 30000):
        if N2 >= N and N2 not in Ns and N2 <= 30000:
            Ns.append(N2)

    betas_hi = [1e2, 1e3, 1e4, 1e5, 1e6, 1e7, 1e8, 1e9, 1e10]

    for N2 in Ns:
        if time.process_time() >= deadline:
            break
        h2 = _resample(best_h, N2)
        h2 = np.maximum(h2, 1e-12)
        h2 = _polish(h2, deadline, betas_hi, maxiter=200)
        c = _C(h2)
        if c < best_C:
            best_C = c
            best_h = h2.copy()
        else:
            if time.process_time() < deadline:
                h3 = _resample(best_h, N2)
                h3 = np.maximum(h3, 1e-12)
                h3 = _polish(h3, deadline, betas_hi, maxiter=200)
                c3 = _C(h3)
                if c3 < best_C:
                    best_C = c3
                    best_h = h3.copy()

    if time.process_time() < deadline:
