        if c_p < best_C:
            best_C, best_h = c_p, h_p.copy()
            base_h = h_p.copy()

    # Try neighboring resolutions, seeding from the current best.
    Ns = sorted(set([max(20, base_N - 50), max(20, base_N - 20),
                     base_N + 20, base_N + 50, base_N + 100, 500, 600]))
    betas_fast = [1e3, 1e5, 1e7, 1e9]
    for N in Ns:
        if time.process_time() >= deadline:
            break
        h0 = _resample(base_h, N)
        h_p, c_p = _polish(h0, deadline, betas_fast, maxiter=200)
        if c_p < best_C:
            best_C, best_h = c_p, h_p.copy()

    # Final deep polish on the best solution at its own resolution.
    if time.process_time() < deadline:
        h_p, c_p = _polish(best_h, deadline, betas_wide)
        if c_p < best_C:
            best_C, best_h = c_p, h_p.copy()

    return np.maximum(np.asarray(best_h, dtype=float), 0.0)
